// SurveyKE v2.2 — M-Pesa + USDT BEP20 withdrawals, lifetime/current balance
const STORE_USERS='surveyke_users',STORE_SESSION='surveyke_session',STORE_SURVEYS='surveyke_surveys',STORE_PARTICIPATIONS='surveyke_participations',STORE_RESPONSES='surveyke_responses',STORE_THEME='surveyke_theme',STORE_NOTIFICATIONS='surveyke_notifications',STORE_PENDING_REF='surveyke_pending_ref',STORE_WITHDRAWALS='surveyke_withdrawals',STORE_PROMOS='surveyke_promos';
const ADMIN_EMAIL='mautinyagah@gmail.com';
const DEMO_URL='https://docs.google.com/forms/';
const PLANS={basic:{key:'basic',label:'Basic',price:0,rank:0,dailyEarningsCap:50,dailySurveyLimit:3,withdrawalMin:2500,icon:'i-star'},silver:{key:'silver',label:'Silver',price:100,rank:1,dailyEarningsCap:100,dailySurveyLimit:5,withdrawalMin:1500,icon:'i-star'},gold:{key:'gold',label:'Gold',price:300,rank:2,dailyEarningsCap:200,dailySurveyLimit:8,withdrawalMin:1000,icon:'i-star'},platinum:{key:'platinum',label:'Platinum',price:500,rank:3,dailyEarningsCap:300,dailySurveyLimit:10,withdrawalMin:500,icon:'i-crown'}};
const ACHIEVEMENTS={first_approval:{icon:'🎯',label:'First Approval'},streak_7:{icon:'🔥',label:'7-Day Streak'},surveys_10:{icon:'📝',label:'10 Surveys'},platinum_member:{icon:'💎',label:'Platinum Member'},referrals_3:{icon:'🤝',label:'3 Referrals'},big_earner:{icon:'💰',label:'KSh 500 Earned'}};
const MCQ_CONFIRM_SECONDS=3,TEXT_READ_SECONDS=6,PARAGRAPH_READ_SECONDS=10,RATING_CONFIRM_SECONDS=2;
const ANIME_SEEDS=['Akira','Yuki','Hana','Kai','Rin','Mei','Sora','Aoi','Ren','Nao','Hikari','Yui'];
const ANIME_URLS=ANIME_SEEDS.map(s=>`https://api.dicebear.com/9.x/lorelei/svg?seed=${s}`);
let currentUser=null,isAdmin=false,surveysCache=[],selectedDirectoryTopic='All',selectedTierFilter='All',searchQuery='',currentView='home',editingAvatar=null,editingName='',selectedPlan=null,adminSurveyType='external',adminQuestions=[],adminParticipationTab='pending',adminSection='add',notifFilter='all',historyFilter='all',installPrompt=null,withdrawMethod='mpesa';
let wizard={active:false,survey:null,answers:{},currentIndex:0,selectedOption:null,timerInterval:null,locked:false};

function readStore(k,f){try{const r=localStorage.getItem(k);if(r===null)return f;return JSON.parse(r);}catch(e){return f;}}
function writeStore(k,v){localStorage.setItem(k,JSON.stringify(v));}
function uid(p){p=p||'id';return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,10);}
async function hashPassword(pw){try{const enc=new TextEncoder().encode(pw+'::surveyke::salt');const buf=await crypto.subtle.digest('SHA-256',enc);return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');}catch(e){return 'plain::'+btoa(pw);}}

function detectBotEnvironment(){try{if(typeof window==='undefined'||typeof document==='undefined')return true;const k='__sk_boot__';localStorage.setItem(k,'1');if(localStorage.getItem(k)!=='1')return true;localStorage.removeItem(k);if(!window.crypto)return true;return false;}catch(e){return true;}}
function markBootStep(id,st){const e=document.getElementById(id);if(!e)return;e.classList.remove('active','done');if(st)e.classList.add(st);}
async function runBootSequence(){const sleep=ms=>new Promise(r=>setTimeout(r,ms));markBootStep('boot-1','active');await sleep(400);try{if(localStorage.getItem(STORE_THEME)===null)localStorage.setItem(STORE_THEME,document.documentElement.getAttribute('data-theme')||'light');}catch(e){}markBootStep('boot-1','done');markBootStep('boot-2','active');await sleep(450);if(detectBotEnvironment()){document.getElementById('boot-error').classList.remove('hidden');document.querySelectorAll('.boot-step').forEach(s=>s.style.opacity='0.3');return;}markBootStep('boot-2','done');markBootStep('boot-3','active');await sleep(400);markBootStep('boot-3','done');await sleep(250);finishBoot();}
function finishBoot(){document.body.classList.remove('booting');const l=document.getElementById('app-loading');if(l)l.style.display='none';try{const p=new URLSearchParams(window.location.search);const ref=p.get('ref');if(ref)localStorage.setItem(STORE_PENDING_REF,ref);}catch(e){}migrate();seedSurveysIfEmpty();restoreSession();ensureDailyReset();fetchAndRenderSurveys();updateNotifBadges();registerSW();setupPWAPrompt();checkStreak();checkAchievements();if(!currentUser&&currentView==='home'){setTimeout(()=>{if(!currentUser)openAuth('signup');},1200);}}
document.addEventListener('DOMContentLoaded',runBootSequence);

function registerSW(){if('serviceWorker'in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').catch(()=>{});});}}
function setupPWAPrompt(){window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const b=document.getElementById('install-btn');if(b)b.classList.remove('hidden');});}
function installPWA(){if(!installPrompt){showToast('App already installed or unavailable.');return;}installPrompt.prompt();installPrompt.userChoice.then(r=>{if(r.outcome==='accepted'){showToast('Installing...');const b=document.getElementById('install-btn');if(b)b.classList.add('hidden');}installPrompt=null;});}

function toggleTheme(){const c=document.documentElement.getAttribute('data-theme')||'light';setTheme(c==='dark'?'light':'dark');}
function setTheme(t){document.documentElement.setAttribute('data-theme',t);try{localStorage.setItem(STORE_THEME,t);}catch(e){}if(currentView==='settings')renderSettings();}

function generateReferralCode(uid){const c=(uid||'').replace(/[^a-z0-9]/gi,'').slice(-6).toUpperCase();return 'SK'+(c||'000000');}
function ensureReferralCode(u){if(!u||!u.id)return 'SK000000';if(u.referralCode)return u.referralCode;const c=generateReferralCode(u.id);const us=readStore(STORE_USERS,[]);const i=us.findIndex(x=>x.id===u.id);if(i!==-1){us[i].referralCode=c;writeStore(STORE_USERS,us);}return c;}
function getReferralLink(){if(!currentUser)return '';const us=readStore(STORE_USERS,[]);const s=us.find(u=>u.id===currentUser.id);const c=s?(s.referralCode||ensureReferralCode(s)):'';return window.location.origin+window.location.pathname+'?ref='+c;}
function copyReferralLink(){const l=getReferralLink();if(navigator.clipboard)navigator.clipboard.writeText(l).then(()=>showToast('Copied!')).catch(()=>{fallbackCopy(l);showToast('Copied!');});else{fallbackCopy(l);showToast('Copied!');}}
function fallbackCopy(t){const ta=document.createElement('textarea');ta.value=t;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');}catch(e){}document.body.removeChild(ta);}
function shareReferralLink(){const l=getReferralLink();const t="Join me on SurveyKE!";if(navigator.share)navigator.share({title:'SurveyKE',text:t,url:l}).catch(()=>{});else{fallbackCopy(l);showToast('Link copied.');}}

function getAllReviews(){if(!currentUser)return [];const ss=readStore(STORE_SURVEYS,[]),ps=readStore(STORE_PARTICIPATIONS,[]);return ps.filter(p=>p.user_id===currentUser.id&&(p.review_status==='approved'||p.review_status==='rejected'||p.review_status==='screened_out'||p.status==='screened_out')).sort((a,b)=>(b.reviewed_at||b.submitted_at||0)-(a.reviewed_at||a.submitted_at||0)).map(p=>{const s=ss.find(x=>x.id===p.survey_id);const st=(p.review_status==='screened_out'||p.status==='screened_out')?'screened_out':p.review_status;return {id:p.id,title:s?s.title:'Deleted',status:st,reward:s?(s.reward||0):0,reviewedAt:p.reviewed_at||p.submitted_at};});}
function getUnreadNotificationsCount(){if(!currentUser||isAdmin)return 0;const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===currentUser.id);if(!u)return 0;const ra=u.notifications_read_at||0;const ps=readStore(STORE_PARTICIPATIONS,[]);const ws=readStore(STORE_WITHDRAWALS,[]);let c=ps.filter(p=>{if(p.user_id!==currentUser.id)return false;if(p.review_status!=='approved'&&p.review_status!=='rejected'&&p.review_status!=='screened_out'&&p.status!=='screened_out')return false;return (p.reviewed_at||0)>ra;}).length;c+=ws.filter(w=>w.user_id===currentUser.id&&(w.status==='completed'||w.status==='rejected')&&(w.updated_at||0)>ra).length;return c;}
function markNotificationsRead(){if(!currentUser)return;const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;us[i].notifications_read_at=Date.now();writeStore(STORE_USERS,us);}
function updateNotifBadges(){const c=getUnreadNotificationsCount();const hb=document.getElementById('header-bell-badge');if(hb){if(c>0){hb.textContent=c>9?'9+':String(c);hb.classList.remove('hidden');}else hb.classList.add('hidden');}document.querySelectorAll('.bottom-nav-item').forEach(it=>{if(it.dataset.tab==='notifications'){let b=it.querySelector('.nav-badge');if(c>0){if(!b){b=document.createElement('span');b.className='nav-badge';it.appendChild(b);}b.textContent=c>9?'9+':String(c);}else if(b)b.remove();}});}
function renderNotifications(){const c=document.getElementById('notifications-content');if(!currentUser){c.innerHTML='<div class="notif-empty"><div class="notif-empty-icon"><svg><use href="#i-bell"/></svg></div><h3>Sign in to view notifications</h3><button class="btn btn-primary" onclick="openAuth(\'signin\')" style="margin-top:16px;">Sign In</button></div>';return;}const all=getAllReviews();const ws=readStore(STORE_WITHDRAWALS,[]).filter(w=>w.user_id===currentUser.id).map(w=>{const ml=w.method==='crypto'?'USDT':'M-Pesa';return {id:w.id,title:`Withdrawal (${ml}) KSh ${w.amount}`,status:w.status==='completed'?'approved':(w.status==='rejected'?'rejected':'pending'),reward:w.amount,reviewedAt:w.updated_at||w.created_at,isWithdrawal:true};});const cm=all.concat(ws).sort((a,b)=>(b.reviewedAt||0)-(a.reviewedAt||0));const counts={all:cm.length,approved:0,rejected:0,screened_out:0};cm.forEach(n=>{if(n.status==='approved')counts.approved++;else if(n.status==='rejected')counts.rejected++;else if(n.status==='screened_out')counts.screened_out++;});let f=notifFilter==='all'?cm:cm.filter(n=>n.status===notifFilter);const filters=[{key:'all',label:'All',count:counts.all},{key:'approved',label:'Approved',count:counts.approved},{key:'rejected',label:'Rejected',count:counts.rejected},{key:'screened_out',label:'Screened',count:counts.screened_out}];let h='<div class="notifications-page"><div class="notifications-page-header"><h2>Notifications</h2><p>Reviews, approvals, updates</p></div><div class="notif-filters">'+filters.map(x=>`<button class="notif-filter ${notifFilter===x.key?'active':''}" onclick="setNotifFilter('${x.key}')">${x.label} <span class="count">${x.count}</span></button>`).join('')+'</div>';if(f.length===0)h+='<div class="notif-empty"><div class="notif-empty-icon"><svg><use href="#i-bell"/></svg></div><h3>No notifications</h3><p>Nothing here yet.</p></div>';else{h+='<div class="notif-list">';f.forEach(n=>{const ia=n.status==='approved';const isS=n.status==='screened_out';const ii=ia?'i-check-circle':(isS?'i-zap':'i-x-circle');const sl=ia?'Approved':(isS?'Screened Out':'Rejected');const ds=n.reviewedAt?new Date(n.reviewedAt).toLocaleString():'—';const rl=ia?(n.isWithdrawal?'Withdrawal processed':'Reward: +KSh '+n.reward):(isS?'Screened out':(n.isWithdrawal?'Withdrawal rejected':'No reward'));h+=`<div class="notif-card notif-${n.status}"><div class="notif-card-icon"><svg><use href="#${ii}"/></svg></div><div class="notif-card-info"><strong>${escapeHtml(n.title)}</strong><small>${rl}</small><small style="margin-top:4px;">${ds}</small><div class="notif-card-status">${sl}</div></div></div>`;});h+='</div>';}h+='</div>';c.innerHTML=h;markNotificationsRead();updateNotifBadges();}
function setNotifFilter(f){notifFilter=f;renderNotifications();}

function todayStr(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function yesterdayStr(){const d=new Date();d.setDate(d.getDate()-1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function getDailyRecord(u){if(!u.daily||u.daily.date!==todayStr())u.daily={date:todayStr(),surveyCount:0,totalRewards:0};return u.daily;}
function ensureDailyReset(){if(!currentUser)return;const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;us[i].daily=getDailyRecord(us[i]);writeStore(STORE_USERS,us);}
function getDailyStatus(){if(!currentUser)return null;const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===currentUser.id);if(!u)return null;const d=getDailyRecord(u);const p=PLANS[u.tier||'basic'];return {date:d.date,surveyCount:d.surveyCount,surveyLimit:p.dailySurveyLimit,totalRewards:d.totalRewards,earningsCap:p.dailyEarningsCap};}
function recordSurveyStart(s){if(!currentUser||isAdmin)return;const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;const d=getDailyRecord(us[i]);d.surveyCount+=1;d.totalRewards+=(s.reward||0);us[i].daily=d;writeStore(STORE_USERS,us);}
function checkStreak(){if(!currentUser||isAdmin)return;const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;const u=us[i];const t=todayStr(),y=yesterdayStr();if(!u.streak)u.streak={days:0,lastClaim:null};if(u.streak.lastClaim===t)return;if(u.streak.lastClaim===y)u.streak.days=Math.min((u.streak.days||0)+1,30);else u.streak.days=1;u.streak.lastClaim=t;const bonus=Math.min(u.streak.days,7)*2;u.bonuses=u.bonuses||[];u.bonuses.push({id:uid('bon'),amount:bonus,type:'streak',description:'Day '+u.streak.days+' streak',created_at:Date.now()});writeStore(STORE_USERS,us);setTimeout(()=>{showToast('🔥 Day '+u.streak.days+' streak! +KSh '+bonus);checkAchievements();},800);}

function userTotalApprovedEarnings(uid){const ps=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===uid&&p.review_status==='approved');const ss=readStore(STORE_SURVEYS,[]);let s=0;ps.forEach(p=>{const sv=ss.find(x=>x.id===p.survey_id);s+=sv?(sv.reward||0):0;});return s;}
function checkAchievements(){if(!currentUser||isAdmin)return;const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;const u=us[i];u.achievements=u.achievements||[];let n=[];const ps=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===u.id);const ap=ps.filter(p=>p.review_status==='approved').length;const sb=ps.filter(p=>p.status==='submitted'||p.review_status==='approved'||p.review_status==='rejected'||p.review_status==='screened_out'||p.status==='screened_out').length;if(ap>=1&&!u.achievements.includes('first_approval')){u.achievements.push('first_approval');n.push('first_approval');}if(u.streak&&u.streak.days>=7&&!u.achievements.includes('streak_7')){u.achievements.push('streak_7');n.push('streak_7');}if(sb>=10&&!u.achievements.includes('surveys_10')){u.achievements.push('surveys_10');n.push('surveys_10');}if(u.tier==='platinum'&&!u.achievements.includes('platinum_member')){u.achievements.push('platinum_member');n.push('platinum_member');}if(u.referrals&&u.referrals.length>=3&&!u.achievements.includes('referrals_3')){u.achievements.push('referrals_3');n.push('referrals_3');}if(userTotalApprovedEarnings(u.id)>=500&&!u.achievements.includes('big_earner')){u.achievements.push('big_earner');n.push('big_earner');}if(n.length>0){writeStore(STORE_USERS,us);n.forEach((a,i)=>setTimeout(()=>showToast('🎉 '+ACHIEVEMENTS[a].icon+' '+ACHIEVEMENTS[a].label),i*800));}}

function getParticipationForSurvey(id){if(!currentUser)return null;const ps=readStore(STORE_PARTICIPATIONS,[]);return ps.find(p=>p.survey_id===id&&p.user_id===currentUser.id);}
function getSurveyUserState(s){if(!currentUser||isAdmin)return 'guest';const p=getParticipationForSurvey(s.id);if(!p)return 'available';if(p.review_status==='screened_out'||p.status==='screened_out')return 'screened_out';if(p.status==='in_progress')return 'in_progress';if(p.status==='started')return 'started_external';if(p.status==='submitted'||p.review_status==='approved'||p.review_status==='rejected'||p.review_status==='reviewed')return 'completed';return 'available';}
function canStartSurvey(s){if(isAdmin)return {allowed:false,reason:'Admins cannot participate.'};if(!currentUser)return {allowed:true};const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===currentUser.id);if(!u)return {allowed:false,reason:'Sign in again.'};const p=PLANS[u.tier||'basic'];const d=getDailyRecord(u);const r=s.reward||0;if(d.surveyCount>=p.dailySurveyLimit)return {allowed:false,reason:'Daily limit of '+p.dailySurveyLimit+' surveys reached.'};if(d.totalRewards+r>p.dailyEarningsCap)return {allowed:false,reason:'Daily cap of KSh '+p.dailyEarningsCap+' reached.'};return {allowed:true};}

function migrate(){const a=readStore(STORE_SURVEYS,null);if(Array.isArray(a)){let ch=false;a.forEach(s=>{if(s.survey_url&&s.survey_url.indexOf('forms.gle/example-survey')!==-1){s.survey_url=DEMO_URL;ch=true;}if(s.tier==='free'){s.tier='basic';ch=true;}if(!s.tier||!PLANS[s.tier]){s.tier='basic';ch=true;}if(typeof s.reward!=='number'){s.reward=20;ch=true;}if(!s.type){s.type='external';ch=true;}if(s.questions&&Array.isArray(s.questions))s.questions.forEach(q=>{if(typeof q.screenOut!=='boolean'){q.screenOut=false;ch=true;}if(!Array.isArray(q.correctOptions)){q.correctOptions=[];ch=true;}});});if(ch)writeStore(STORE_SURVEYS,a);}const us=readStore(STORE_USERS,null);if(Array.isArray(us)){let ch=false;us.forEach(u=>{if(u.tier==='free'){u.tier='basic';ch=true;}if(!u.tier||!PLANS[u.tier]){u.tier='basic';ch=true;}if(!u.referralCode){u.referralCode=generateReferralCode(u.id);ch=true;}if(!Array.isArray(u.referrals)){u.referrals=[];ch=true;}if(!Array.isArray(u.bonuses)){u.bonuses=[];ch=true;}if(!Array.isArray(u.achievements)){u.achievements=[];ch=true;}if(!Array.isArray(u.logins)){u.logins=[];ch=true;}if(!u.daily||u.daily.date!==todayStr()){u.daily={date:todayStr(),surveyCount:0,totalRewards:0};ch=true;}if(!u.username){const b=(u.name||u.email.split('@')[0]).toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,15);u.username=b||'user'+Math.floor(Math.random()*9999);ch=true;}});if(ch)writeStore(STORE_USERS,us);}if(!Array.isArray(readStore(STORE_RESPONSES,null)))writeStore(STORE_RESPONSES,[]);if(!Array.isArray(readStore(STORE_WITHDRAWALS,null)))writeStore(STORE_WITHDRAWALS,[]);if(!Array.isArray(readStore(STORE_PROMOS,null)))writeStore(STORE_PROMOS,[]);}
function seedSurveysIfEmpty(){const e=readStore(STORE_SURVEYS,null);if(Array.isArray(e)&&e.length>0)return;const now=Date.now();writeStore(STORE_SURVEYS,[{id:uid('sur'),title:'Digital ID Public Feedback',category:'Public Policy',description:'Share your views on the proposed national digital ID.',estimated_minutes:5,duration:'5 mins',status:'published',type:'external',survey_url:DEMO_URL,eligibility:'Kenyan residents 18+.',instructions:'Answer honestly.',tier:'basic',reward:15,created_at:now-500000},{id:uid('sur'),title:'Public Transport Satisfaction',category:'Transport',description:'Quick feedback on your recent matatu experience.',estimated_minutes:4,duration:'4 mins',status:'published',type:'external',survey_url:DEMO_URL,eligibility:'Commuters.',instructions:'Focus on last journey.',tier:'basic',reward:20,created_at:now-400000},{id:uid('sur'),title:'Mobile Money Usage Study',category:'Finance',description:'How Kenyans use mobile money platforms.',estimated_minutes:7,duration:'7 mins',status:'published',type:'external',survey_url:DEMO_URL,eligibility:'Users.',instructions:'Recent activity.',tier:'silver',reward:30,created_at:now-300000},{id:uid('sur'),title:'Consumer Brand Preferences',category:'Consumer Goods',description:'Which brands you trust and why.',estimated_minutes:8,duration:'8 mins',status:'published',type:'external',survey_url:DEMO_URL,eligibility:'Shoppers.',instructions:'Answer honestly.',tier:'gold',reward:55,created_at:now-200000},{id:uid('sur'),title:'Health Services Experience',category:'Health',description:'Premium healthcare study.',estimated_minutes:10,duration:'10 mins',status:'published',type:'external',survey_url:DEMO_URL,eligibility:'Adults 18+.',instructions:'Anonymous.',tier:'platinum',reward:100,created_at:now-100000}]);}
function restoreSession(){const s=readStore(STORE_SESSION,null);if(s&&s.userId){const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===s.userId);if(u){currentUser={id:u.id,email:u.email,name:u.name||u.email.split('@')[0],username:u.username||u.email.split('@')[0],avatar:u.avatar||null,tier:u.tier||'basic',referralCode:u.referralCode||ensureReferralCode(u),referrals:u.referrals||[]};isAdmin=u.email.toLowerCase()===ADMIN_EMAIL.toLowerCase();}else writeStore(STORE_SESSION,null);}updateAuthUI();}

function clearWizardTimer(){if(wizard.timerInterval){clearInterval(wizard.timerInterval);wizard.timerInterval=null;}}
function exitWizard(){clearWizardTimer();wizard.active=false;navigate('surveys');}
function navigate(v,p){clearWizardTimer();currentView=v;window.scrollTo({top:0,behavior:'smooth'});['view-home','view-surveys','view-detail','view-take-survey','view-wallet','view-history','view-notifications','view-profile','view-settings','view-static','view-admin'].forEach(id=>{const e=document.getElementById(id);if(e)e.classList.add('hidden');});if(v==='home'){document.getElementById('view-home').classList.remove('hidden');renderSurveyOfDay();renderHomeSurveys();updateBottomNav('home');}else if(v==='surveys'){document.getElementById('view-surveys').classList.remove('hidden');renderSurveysPlanBanner();renderTierBanners();renderDirectorySurveys();updateBottomNav('surveys');}else if(v==='detail'&&p){document.getElementById('view-detail').classList.remove('hidden');renderSurveyDetail(p);updateBottomNav('surveys');}else if(v==='take-survey'&&p){document.getElementById('view-take-survey').classList.remove('hidden');startOrResumeWizard(p);updateBottomNav('surveys');}else if(v==='wallet'){document.getElementById('view-wallet').classList.remove('hidden');renderWallet();updateBottomNav('wallet');}else if(v==='history'){document.getElementById('view-history').classList.remove('hidden');renderHistory();updateBottomNav('profile');}else if(v==='notifications'){document.getElementById('view-notifications').classList.remove('hidden');renderNotifications();updateBottomNav('notifications');}else if(v==='profile'){document.getElementById('view-profile').classList.remove('hidden');renderProfile();updateBottomNav('profile');}else if(v==='settings'){document.getElementById('view-settings').classList.remove('hidden');renderSettings();updateBottomNav('profile');}else if(v==='static'&&p){document.getElementById('view-static').classList.remove('hidden');renderStaticPage(p);updateBottomNav(null);}else if(v==='admin'){if(!isAdmin){showToast('Admin only.');navigate('home');return;}document.getElementById('view-admin').classList.remove('hidden');renderAdminDashboard();updateBottomNav(null);}}
function getCurrentTab(){if(currentView==='home')return 'home';if(currentView==='surveys'||currentView==='detail'||currentView==='take-survey')return 'surveys';if(currentView==='wallet')return 'wallet';if(currentView==='notifications')return 'notifications';if(currentView==='profile'||currentView==='settings'||currentView==='history')return 'profile';return null;}
function updateBottomNav(t){document.querySelectorAll('.bottom-nav-item').forEach(i=>{if(i.dataset.tab===t)i.classList.add('active');else i.classList.remove('active');});updateNotifBadges();}

function getUserTier(){return currentUser?(currentUser.tier||'basic'):'basic';}
function canAccessSurvey(t){if(!currentUser)return true;return PLANS[getUserTier()].rank>=PLANS[t||'basic'].rank;}
function tierBadgeHTML(t){t=t||'basic';if(!PLANS[t])t='basic';return `<span class="tier-badge tier-${t}"><svg><use href="#${PLANS[t].icon}"/></svg>${PLANS[t].label}</span>`;}

function renderSurveysPlanBanner(){const e=document.getElementById('surveys-plan-banner');if(!e)return;if(isAdmin){e.innerHTML='<div class="surveys-plan-banner"><div class="surveys-plan-left"><div><strong>Admin view</strong><small>Manage only</small></div></div><button class="btn btn-outline btn-sm" onclick="navigate(\'admin\')">Admin</button></div>';return;}if(!currentUser){e.innerHTML='<div class="surveys-plan-banner"><div class="surveys-plan-left"><div><strong>Guest</strong><small>Sign in to participate</small></div></div><button class="btn btn-primary btn-sm" onclick="openAuth(\'signin\')">Sign In</button></div>';return;}const t=getUserTier(),p=PLANS[t];e.innerHTML=`<div class="surveys-plan-banner"><div class="surveys-plan-left"><div><strong>Plan: ${p.label}</strong><small>KSh ${p.dailyEarningsCap}/day · ${p.dailySurveyLimit} surveys/day · Withdraw at KSh ${p.withdrawalMin}</small></div></div><button class="btn btn-outline btn-sm" onclick="openPlanModal()"><svg style="width:14px;height:14px;"><use href="#i-crown"/></svg>Change</button></div>`;}
function renderTierBanners(){const e=document.getElementById('surveys-tier-banners');if(!e)return;const ts=['basic','silver','gold','platinum'];const ur=currentUser?PLANS[getUserTier()].rank:-1;let h='';ts.forEach(t=>{const p=PLANS[t];const c=surveysCache.filter(s=>(s.tier||'basic')===t).length;const a=selectedTierFilter===t;const l=ur>=0&&PLANS[t].rank>ur;h+=`<div class="tier-banner tier-${t}${a?' active':''}${l?' locked-banner':''}" onclick="filterByTier('${t}')">${l?'<span class="lock-mini">🔒</span>':''}<strong>${p.label}</strong><small>${c} survey${c===1?'':'s'}</small></div>`;});h+=`<div class="tier-banner${selectedTierFilter==='All'?' active':''}" onclick="filterByTier('All')"><strong>All</strong><small>${surveysCache.length} total</small></div>`;e.innerHTML=h;}
function filterByTier(t){selectedTierFilter=t;renderTierBanners();renderDirectorySurveys();}
function onSurveySearch(v){searchQuery=v.trim().toLowerCase();const b=document.getElementById('search-clear-btn');if(b){if(searchQuery.length>0)b.classList.remove('hidden');else b.classList.add('hidden');}renderDirectorySurveys();}
function clearSurveySearch(){searchQuery='';const i=document.getElementById('surveys-search');if(i)i.value='';const b=document.getElementById('search-clear-btn');if(b)b.classList.add('hidden');renderDirectorySurveys();}
function fetchAndRenderSurveys(){try{const a=readStore(STORE_SURVEYS,[]);surveysCache=(a||[]).filter(s=>{if(s.status!=='published')return false;if(s.type==='external'&&(!s.survey_url||!s.survey_url.startsWith('https://')))return false;if(s.type==='external'&&s.survey_url.indexOf('example.com')!==-1)return false;return true;}).sort((a,b)=>(b.created_at||0)-(a.created_at||0));renderSurveyOfDay();renderHomeSurveys();renderDirectorySurveys();renderSurveysPlanBanner();if(currentView==='surveys')renderTierBanners();}catch(e){console.error(e);surveysCache=[];}}
function getSurveyOfDay(){if(surveysCache.length===0)return null;const t=todayStr();let h=0;for(let i=0;i<t.length;i++)h=((h<<5)-h)+t.charCodeAt(i);h=Math.abs(h);return surveysCache[h%surveysCache.length];}
function renderSurveyOfDay(){const c=document.getElementById('survey-of-day-container');if(!c)return;const s=getSurveyOfDay();if(!s){c.innerHTML='';return;}c.innerHTML=`<div class="survey-of-day"><div class="sod-badge"><svg><use href="#i-star"/></svg>Survey of the Day</div><h3>${escapeHtml(s.title)}</h3><div class="sod-meta"><span>⏱ ${escapeHtml(s.estimated_minutes||s.duration||'5')} mins</span><span>💰 KSh ${s.reward||20}</span><span>${tierBadgeHTML(s.tier)}</span></div><p>${escapeHtml(s.description||'')}</p><div class="sod-actions"><button class="btn btn-light" onclick="navigate('detail','${s.id}')">Participate <svg><use href="#i-arrow"/></svg></button><button class="btn btn-light" style="background:rgba(255,255,255,.15);color:#fff;" onclick="navigate('surveys')">See All</button></div></div>`;}
function surveyCardHTML(s){const t=s.tier||'basic';const st=getSurveyUserState(s);const l=!isAdmin&&currentUser&&!canAccessSurvey(t);let cls='card-link',lbl='Participate →';if(isAdmin)lbl='View →';else if(st==='completed')lbl='Completed ✓';else if(st==='screened_out'){lbl='Screened';cls='card-link locked';}else if(st==='in_progress')lbl='Continue →';else if(st==='started_external')lbl='Reopen →';else if(l){cls='card-link locked';lbl='Upgrade →';}return `<div class="survey-card ${l?'locked':''}"><div class="card-top"><span class="cat-chip">${escapeHtml(s.category||'General')}</span>${tierBadgeHTML(t)}</div><h3>${escapeHtml(s.title)}</h3><p class="clamp">${escapeHtml(s.description||'')}</p><div class="card-bottom"><span class="meta-chip"><svg><use href="#i-clock"/></svg>${escapeHtml(s.estimated_minutes||s.duration||'5')} mins · KSh ${s.reward||20}</span><button class="${cls}" onclick="navigate('detail','${s.id}')">${lbl}</button></div></div>`;}
function renderHomeSurveys(){const c=document.getElementById('home-surveys-grid');if(surveysCache.length===0){c.innerHTML='<div class="state-box" style="grid-column:1/-1;"><strong>No active surveys</strong></div>';return;}c.innerHTML=surveysCache.slice(0,3).map(surveyCardHTML).join('');}
function renderDirectorySurveys(){const c=document.getElementById('directory-surveys-grid');let l=surveysCache;if(selectedTierFilter!=='All')l=l.filter(s=>(s.tier||'basic')===selectedTierFilter);if(selectedDirectoryTopic!=='All')l=l.filter(s=>s.category===selectedDirectoryTopic);if(searchQuery)l=l.filter(s=>(s.title||'').toLowerCase().indexOf(searchQuery)!==-1||(s.description||'').toLowerCase().indexOf(searchQuery)!==-1||(s.category||'').toLowerCase().indexOf(searchQuery)!==-1);if(l.length===0){let em='No surveys match.';if(searchQuery)em=`No results for "<strong>${escapeHtml(searchQuery)}</strong>".`;else if(selectedTierFilter!=='All')em=`No ${PLANS[selectedTierFilter].label} surveys. <button class="card-link" onclick="filterByTier('All');filterDirectoryTopic('All')">Browse all</button>.`;else em=`No surveys. <button class="card-link" onclick="filterDirectoryTopic('All')">All</button>.`;c.innerHTML=`<div class="state-box" style="grid-column:1/-1;"><strong>No surveys</strong><p>${em}</p></div>`;return;}c.innerHTML=l.map(surveyCardHTML).join('');}
function filterDirectoryTopic(t){selectedDirectoryTopic=t;document.querySelectorAll('#directory-topic-chips .topic-chip').forEach(c=>{if(c.textContent.trim()===t||(t==='All'&&c.textContent.includes('All')))c.classList.add('active');else c.classList.remove('active');});renderDirectorySurveys();}

function renderSurveyDetail(id){const s=surveysCache.find(x=>x.id===id);const c=document.getElementById('survey-detail-content');if(!s){c.innerHTML='<div class="state-box"><strong>Not found</strong></div>';return;}const dm=s.survey_url===DEMO_URL&&s.type==='external'?'<div class="notice show info" style="margin-bottom:12px;"><strong>Demo survey</strong></div>':'';const el=s.eligibility?`<div class="detail-section"><h3>Eligibility</h3><p class="detail-text">${escapeHtml(s.eligibility)}</p></div>`:'';const ins=s.instructions?`<div class="detail-section"><h3>Instructions</h3><p class="detail-text">${escapeHtml(s.instructions)}</p></div>`:'';const t=s.tier||'basic';const isI=s.type==='internal';const qc=isI&&Array.isArray(s.questions)?s.questions.length:0;const st=getSurveyUserState(s);let part='';if(isAdmin)part='<div class="admin-notice"><strong>Admin view</strong><p>Cannot participate.</p><button class="btn btn-primary" onclick="navigate(\'admin\')">Manage</button></div>';else if(!currentUser)part='<div class="participate-box"><h3>Sign in</h3><div class="btn-row"><button class="btn btn-primary" onclick="openAuth(\'signin\')">Sign In</button></div></div>';else if(!canAccessSurvey(t))part=`<div class="upgrade-notice"><h3>${PLANS[t].label} required</h3><button class="btn btn-primary" onclick="openPlanModal()">Upgrade</button></div>`;else if(st==='screened_out')part='<div class="participate-box" style="border-color:var(--amber-border);background:var(--amber-bg);"><h3 style="color:var(--amber);">Screened out</h3></div>';else if(st==='completed')part='<div class="participate-box" style="border-color:var(--green);background:var(--green-soft);"><h3>Completed ✓</h3></div>';else if(st==='in_progress')part=`<div class="participate-box"><h3>Continue</h3>${dm}<div class="btn-row"><button class="btn btn-primary" onclick="navigate('take-survey','${s.id}')">Continue →</button></div></div>`;else if(st==='started_external')part=`<div class="participate-box"><h3>In Progress</h3>${dm}<div class="btn-row"><button class="btn btn-primary" onclick="reopenExternal('${s.id}')">Reopen</button></div></div>`;else{const dc=canStartSurvey(s);if(!dc.allowed)part=`<div class="participate-box" style="border-color:var(--danger);background:var(--danger-bg);"><h3 style="color:var(--danger);">Not available</h3><p>${escapeHtml(dc.reason)}</p></div>`;else{const bl=isI?'Start':'Proceed External';const bi=isI?'#i-arrow':'#i-external';const tl=isI?`${qc} questions, may screen out`:'Hosted externally';part=`<div class="participate-box"><h3>Take Survey</h3><p>${tl}</p>${dm}<div class="btn-row"><button class="btn btn-primary" onclick="startSurvey('${s.id}')">${bl} <svg><use href="${bi}"/></svg></button></div></div>`;}}const tb=isI?'<span class="cat-chip" style="background:var(--tier-platinum-bg);color:var(--tier-platinum);">In-App</span>':'';const rel=surveysCache.filter(x=>x.category===s.category&&x.id!==s.id).slice(0,3);const rh=rel.length>0?`<div class="detail-section" style="margin-top:32px;"><h3>Similar</h3><div class="survey-grid" style="margin-top:12px;">${rel.map(surveyCardHTML).join('')}</div></div>`:'';c.innerHTML=`<div class="detail-card"><div class="card-top" style="margin-bottom:14px;flex-wrap:wrap;gap:8px;"><span class="cat-chip">${escapeHtml(s.category)}</span>${tb}${tierBadgeHTML(t)}</div><h1>${escapeHtml(s.title)}</h1><div style="display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap;"><span class="meta-chip">⏱ ${escapeHtml(s.estimated_minutes||s.duration||'5')} mins</span><span class="meta-chip">💰 KSh ${s.reward||20}</span>${isI?`<span class="meta-chip">📝 ${qc} questions</span>`:''}</div><p class="detail-text">${escapeHtml(s.description)}</p>${el}${ins}${part}</div>${rh}`;}
function startSurvey(id){if(isAdmin){showToast('Admins cannot participate.');return;}if(!currentUser){openAuth('signin');return;}const s=readStore(STORE_SURVEYS,[]).find(x=>x.id===id);if(!s)return;if(!canAccessSurvey(s.tier||'basic')){showToast('Upgrade');return;}const e=getParticipationForSurvey(id);if(e){if(e.status==='in_progress'){navigate('take-survey',id);return;}if(e.status==='started'){reopenExternal(id);return;}showToast('Already taken.');return;}if(s.type==='internal'){const dc=canStartSurvey(s);if(!dc.allowed){showToast(dc.reason);return;}navigate('take-survey',id);}else startExternalSurvey(id);}
function reopenExternal(id){const s=readStore(STORE_SURVEYS,[]).find(x=>x.id===id);if(!s||!s.survey_url)return;showToast('Reopening...');window.open(s.survey_url,'_blank','noopener,noreferrer');}
function startExternalSurvey(id){if(isAdmin)return;if(!currentUser){openAuth('signin');return;}const s=readStore(STORE_SURVEYS,[]).find(x=>x.id===id);if(!s||!s.survey_url)return;if(getParticipationForSurvey(id)){showToast('Already started');return;}const dc=canStartSurvey(s);if(!dc.allowed){showToast(dc.reason);return;}try{const ps=readStore(STORE_PARTICIPATIONS,[]);ps.push({id:uid('part'),survey_id:id,user_id:currentUser.id,status:'started',review_status:'pending',submitted_at:Date.now(),started_at:Date.now()});writeStore(STORE_PARTICIPATIONS,ps);recordSurveyStart(s);showToast('Opening...');setTimeout(()=>window.open(s.survey_url,'_blank','noopener,noreferrer'),700);}catch(e){window.open(s.survey_url,'_blank','noopener,noreferrer');}}

function startOrResumeWizard(id){if(isAdmin){navigate('admin');return;}if(!currentUser){openAuth('signin');navigate('surveys');return;}const s=readStore(STORE_SURVEYS,[]).find(x=>x.id===id);if(!s||s.type!=='internal'){navigate('surveys');return;}if(!canAccessSurvey(s.tier||'basic')){showToast('Upgrade');navigate('surveys');return;}const ps=readStore(STORE_PARTICIPATIONS,[]);let p=ps.find(x=>x.survey_id===id&&x.user_id===currentUser.id);if(p&&(p.status==='submitted'||p.review_status==='approved'||p.review_status==='rejected'||p.review_status==='reviewed'||p.review_status==='screened_out'||p.status==='screened_out')){showToast('Cannot retake');navigate('detail',id);return;}if(!p){const dc=canStartSurvey(s);if(!dc.allowed){showToast(dc.reason);navigate('surveys');return;}p={id:uid('part'),survey_id:id,user_id:currentUser.id,status:'in_progress',review_status:'in_progress',answers:{},wizard_index:0,started_at:Date.now(),updated_at:Date.now()};ps.push(p);writeStore(STORE_PARTICIPATIONS,ps);recordSurveyStart(s);}wizard={active:true,survey:s,answers:p.answers||{},currentIndex:Math.min(p.wizard_index||0,(s.questions||[]).length-1),selectedOption:null,timerInterval:null,locked:false};if(wizard.currentIndex<0)wizard.currentIndex=0;renderWizard();}
function renderWizard(){const c=document.getElementById('take-survey-content');const s=wizard.survey;const qs=s.questions||[];if(qs.length===0){c.innerHTML='<div class="state-box"><strong>No questions</strong></div>';return;}const q=qs[wizard.currentIndex];const total=qs.length;const cur=wizard.currentIndex+1;const isLast=wizard.currentIndex===total-1;const isFirst=wizard.currentIndex===0;const sa=wizard.answers[q.id];let inp='',tl='';if(q.type==='mcq'){tl='Multiple Choice';wizard.selectedOption=(sa!==undefined&&sa!=='')?sa:null;wizard.locked=false;inp='<div class="wizard-options-vertical">'+q.options.map((opt,i)=>{const l=String.fromCharCode(65+i);const sel=wizard.selectedOption===opt?' selected':'';return `<button type="button" class="wizard-option-btn${sel}" data-value="${escapeHtml(opt)}" onclick="wizardPickOption(this)"><span class="wizard-opt-bullet">${l}</span><span class="wizard-opt-label">${escapeHtml(opt)}</span><span class="wizard-opt-check">✓</span></button>`;}).join('')+'</div>';}else if(q.type==='rating'){tl='Rating';wizard.selectedOption=(sa!==undefined&&sa!=='')?sa:null;wizard.locked=false;const lbls={1:'Very Poor',2:'Poor',3:'Average',4:'Good',5:'Excellent'};inp='<div class="wizard-rating-vertical">';for(let n=1;n<=5;n++){const sel=String(wizard.selectedOption)===String(n)?' selected':'';const st='★'.repeat(n)+'☆'.repeat(5-n);inp+=`<button type="button" class="wizard-rating-btn${sel}" onclick="wizardPickRating(${n})"><span class="wizard-rating-num">${n}</span><span>${lbls[n]}</span><span class="wizard-rating-stars">${st}</span></button>`;}inp+='</div>';}else if(q.type==='text'){tl='Short Text';inp=`<input type="text" class="wizard-text-input" id="wizard-text-input" placeholder="Type answer..." value="${escapeHtml(sa||'')}" autocomplete="off">`;}else if(q.type==='paragraph'){tl='Paragraph';inp=`<textarea class="wizard-text-input" id="wizard-text-input" placeholder="Type answer...">${escapeHtml(sa||'')}</textarea>`;}c.innerHTML=`<div class="wizard-shell"><div class="wizard-float-pill" id="wizard-float-pill"><span class="wfp-qnum"><svg><use href="#i-book"/></svg>Q${cur}/${total}</span><span class="wfp-timer ready" id="wfp-timer"><span class="wfp-dot"></span> <span id="wfp-timer-text">Ready</span></span></div><div class="wizard-card"><div class="wizard-q-header"><span class="wizard-q-num">Question ${cur}</span><span class="wizard-q-type">${tl}</span></div><p class="wizard-q-text">${escapeHtml(q.question)}${q.required?'<span class="req">*</span>':''}</p>${inp}<div class="wizard-footer"><button type="button" class="wizard-prev-btn" ${isFirst?'disabled':''} onclick="wizardPrev()">← Previous</button><button type="button" class="wizard-next-btn" id="wizard-next-btn" disabled onclick="wizardNext()">${isLast?'Submit ✓':'Continue →'}</button></div></div></div>`;const ti=document.getElementById('wizard-text-input');if(ti){blockPaste(ti);ti.addEventListener('input',updateNextBtnState);}if(q.type==='mcq'||q.type==='rating'){if(wizard.selectedOption!==null)wizardStartConfirmTimer(q,wizard.selectedOption);}else wizardStartReadingTimer(q);updateNextBtnState();}
function blockPaste(el){el.addEventListener('paste',e=>{e.preventDefault();showToast('Pasting disabled.');});el.addEventListener('drop',e=>e.preventDefault());el.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['v','V','x','X'].includes(e.key)){e.preventDefault();showToast('Copy/paste disabled.');}});el.addEventListener('copy',e=>e.preventDefault());el.addEventListener('cut',e=>e.preventDefault());}
function wizardStartConfirmTimer(q,v){clearWizardTimer();wizard.locked=false;let r=q.type==='rating'?RATING_CONFIRM_SECONDS:MCQ_CONFIRM_SECONDS;updateFloatTimer(r,'counting');updateNextBtnState();wizard.timerInterval=setInterval(()=>{r--;if(r<=0){clearWizardTimer();wizard.locked=true;updateFloatTimer(0,'ready');updateNextBtnState();}else updateFloatTimer(r,'counting');},1000);}
function wizardStartReadingTimer(q){clearWizardTimer();wizard.locked=false;let r=q.type==='paragraph'?PARAGRAPH_READ_SECONDS:TEXT_READ_SECONDS;updateFloatTimer(r,'counting');updateNextBtnState();wizard.timerInterval=setInterval(()=>{r--;if(r<=0){clearWizardTimer();wizard.locked=true;updateFloatTimer(0,'ready');updateNextBtnState();}else updateFloatTimer(r,'counting');},1000);}
function updateFloatTimer(s,m){const p=document.getElementById('wizard-float-pill');const e=document.getElementById('wfp-timer');const t=document.getElementById('wfp-timer-text');if(!e||!t)return;if(m==='counting'){e.className='wfp-timer counting';t.textContent=s+'s';if(p){p.classList.remove('pulse');void p.offsetWidth;p.classList.add('pulse');}}else{e.className='wfp-timer ready';t.textContent='Ready';}}
function wizardPickOption(b){if(wizard.locked)return;document.querySelectorAll('.wizard-option-btn').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');wizard.selectedOption=b.dataset.value;wizardStartConfirmTimer(wizard.survey.questions[wizard.currentIndex],wizard.selectedOption);}
function wizardPickRating(v){if(wizard.locked)return;document.querySelectorAll('.wizard-rating-btn').forEach(b=>b.classList.remove('selected'));const bs=document.querySelectorAll('.wizard-rating-btn');if(bs[v-1])bs[v-1].classList.add('selected');wizard.selectedOption=v;wizardStartConfirmTimer(wizard.survey.questions[wizard.currentIndex],v);}
function updateNextBtnState(){const b=document.getElementById('wizard-next-btn');if(!b)return;const q=wizard.survey.questions[wizard.currentIndex];let h=false;if(q.type==='mcq'||q.type==='rating')h=wizard.selectedOption!==null&&wizard.selectedOption!==undefined&&wizard.selectedOption!=='';else{const i=document.getElementById('wizard-text-input');h=i?(i.value.trim().length>0||!q.required):false;}b.disabled=!(wizard.locked&&h);}
function saveWizardProgress(){const ps=readStore(STORE_PARTICIPATIONS,[]);const i=ps.findIndex(p=>p.survey_id===wizard.survey.id&&p.user_id===currentUser.id);if(i===-1)return;ps[i].answers=wizard.answers;ps[i].wizard_index=wizard.currentIndex;ps[i].updated_at=Date.now();writeStore(STORE_PARTICIPATIONS,ps);showAutosave();}
function showAutosave(){let e=document.querySelector('.autosave-indicator');if(!e){e=document.createElement('div');e.className='autosave-indicator';e.textContent='✓ Auto-saved';document.body.appendChild(e);}e.classList.add('show');clearTimeout(window.__autosaveTimeout);window.__autosaveTimeout=setTimeout(()=>e.classList.remove('show'),1500);}
function wizardPrev(){if(wizard.currentIndex===0)return;const q=wizard.survey.questions[wizard.currentIndex];if(q.type==='mcq'||q.type==='rating'){if(wizard.selectedOption!==null)wizard.answers[q.id]=wizard.selectedOption;}else{const i=document.getElementById('wizard-text-input');if(i)wizard.answers[q.id]=i.value.trim();}saveWizardProgress();wizard.currentIndex--;wizard.selectedOption=null;wizard.locked=false;clearWizardTimer();renderWizard();}
function wizardNext(){const q=wizard.survey.questions[wizard.currentIndex];if(q.type==='mcq'||q.type==='rating')wizard.answers[q.id]=wizard.selectedOption;else{const i=document.getElementById('wizard-text-input');wizard.answers[q.id]=i?i.value.trim():'';}if(q.required&&(wizard.answers[q.id]===''||wizard.answers[q.id]===null||wizard.answers[q.id]===undefined)){showToast('Please answer.');return;}saveWizardProgress();if(q.type==='mcq'&&q.screenOut){const b=document.getElementById('wizard-next-btn');if(b){b.disabled=true;b.innerHTML='<span class="btn-spinner"></span>Checking...';}setTimeout(()=>{const c=q.correctOptions||[];const si=(q.options||[]).indexOf(wizard.answers[q.id]);if(c.indexOf(si)===-1)wizardScreenOut();else advanceWizard();},900);}else advanceWizard();}
function advanceWizard(){wizard.currentIndex++;wizard.selectedOption=null;wizard.locked=false;if(wizard.currentIndex>=wizard.survey.questions.length)wizardFinish();else renderWizard();}
function wizardScreenOut(){clearWizardTimer();wizard.active=false;const s=wizard.survey;const ps=readStore(STORE_PARTICIPATIONS,[]);const i=ps.findIndex(p=>p.survey_id===s.id&&p.user_id===currentUser.id);if(i!==-1){ps[i].status='screened_out';ps[i].review_status='screened_out';ps[i].screened_out_at=Date.now();ps[i].submitted_at=Date.now();writeStore(STORE_PARTICIPATIONS,ps);}const c=document.getElementById('take-survey-content');c.innerHTML='<div class="wizard-shell"><div class="wizard-card screenout-screen"><div class="screenout-icon"><svg><use href="#i-x-circle"/></svg></div><h2>Screened Out</h2><p>Your answer didn\'t meet the criteria. You cannot proceed.</p><div class="btn-row" style="justify-content:center;"><button class="btn btn-primary" onclick="navigate(\'surveys\')">Browse Other Surveys</button></div></div></div>';}
function wizardFinish(){clearWizardTimer();const s=wizard.survey;const rs=readStore(STORE_RESPONSES,[]);const ei=rs.findIndex(r=>r.survey_id===s.id&&r.user_id===currentUser.id);if(ei!==-1){rs[ei].answers=wizard.answers;rs[ei].submitted_at=Date.now();}else rs.push({id:uid('resp'),survey_id:s.id,user_id:currentUser.id,answers:wizard.answers,submitted_at:Date.now()});writeStore(STORE_RESPONSES,rs);const ps=readStore(STORE_PARTICIPATIONS,[]);const i=ps.findIndex(p=>p.survey_id===s.id&&p.user_id===currentUser.id);if(i!==-1){ps[i].status='submitted';ps[i].review_status='pending';ps[i].submitted_at=Date.now();ps[i].answers=wizard.answers;ps[i].wizard_index=(s.questions||[]).length;writeStore(STORE_PARTICIPATIONS,ps);}wizard.active=false;try{if(window.confetti)confetti({particleCount:120,spread:70,origin:{y:.6}});}catch(e){}const c=document.getElementById('take-survey-content');c.innerHTML=`<div class="wizard-shell"><div class="wizard-card thank-you-card"><div class="thank-you-icon"><svg><use href="#i-check-circle"/></svg></div><h2 style="font-family:Manrope,sans-serif;font-size:26px;letter-spacing:-.8px;margin:0 0 10px;color:var(--ink);">🎉 Submitted!</h2><p style="color:var(--muted-strong);font-size:14.5px;max-width:400px;margin:0 auto 22px;">Your response to <strong>${escapeHtml(s.title)}</strong> is submitted.</p><div class="btn-row" style="justify-content:center;"><button class="btn btn-primary" onclick="navigate('surveys')">More Surveys</button><button class="btn btn-outline" onclick="navigate('wallet')">Wallet</button></div></div></div>`;setTimeout(checkAchievements,500);}

function getUserBalance(uid){const ps=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===uid&&p.review_status==='approved');const ss=readStore(STORE_SURVEYS,[]);let earned=0;ps.forEach(p=>{const s=ss.find(x=>x.id===p.survey_id);if(s)earned+=s.reward||0;});const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===uid);const bonuses=(u&&u.bonuses)?u.bonuses.reduce((s,b)=>s+(b.amount||0),0):0;const ws=readStore(STORE_WITHDRAWALS,[]).filter(w=>w.user_id===uid&&(w.status==='completed'||w.status==='processing'||w.status==='pending'));const withdrawn=ws.reduce((s,w)=>s+(w.amount||0),0);return {earned:earned,bonuses:bonuses,withdrawn:withdrawn,lifetime:earned+bonuses,available:earned+bonuses-withdrawn};}

function renderWallet(){if(isAdmin){renderAdminWallet();return;}const c=document.getElementById('wallet-content');if(!currentUser){c.innerHTML='<div class="empty-state"><div class="empty-icon"><svg><use href="#i-wallet"/></svg></div><h2>Sign in to view wallet</h2><button class="btn btn-primary" onclick="openAuth(\'signin\')" style="margin-top:16px;">Sign In</button></div>';return;}const us=readStore(STORE_USERS,[]);const st=us.find(u=>u.id===currentUser.id)||{};const tier=st.tier||'basic';const plan=PLANS[tier];const bal=getUserBalance(currentUser.id);const lifetime=bal.lifetime;const current=bal.available;const pendingParts=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===currentUser.id&&(p.review_status==='pending'||p.review_status==='reviewed'||p.review_status==='in_progress'));const ss=readStore(STORE_SURVEYS,[]);let pending=0;pendingParts.forEach(p=>{const s=ss.find(x=>x.id===p.survey_id);if(s)pending+=s.reward||0;});const threshold=plan.withdrawalMin;const canWithdraw=current>=threshold;const progress=Math.min(100,(current/threshold)*100);const remaining=Math.max(0,threshold-current);const daily=getDailyStatus();const sp=daily?Math.min(100,(daily.surveyCount/daily.surveyLimit)*100):0;const ep=daily?Math.min(100,(daily.totalRewards/daily.earningsCap)*100):0;const wStart=(()=>{const d=new Date();d.setDate(d.getDate()-d.getDay());return d.toISOString().slice(0,10);})();const wParts=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===currentUser.id&&(p.submitted_at||0)>=new Date(wStart).getTime());const wCount=wParts.length;const wGoal=5;const wPct=Math.min(100,(wCount/wGoal)*100);const streak=st.streak||{days:0};const streakHTML=streak.days>0?`<div class="streak-display"><div class="streak-icon">🔥</div><div class="streak-info"><strong>Day ${streak.days} Streak</strong><small>+KSh ${Math.min(streak.days,7)*2} daily bonus</small></div></div>`:'';const weeklyHTML=`<div class="weekly-challenge"><div class="weekly-challenge-header"><h3>🏆 Weekly Challenge</h3><span class="reward">+KSh 100</span></div><p>Complete 5 surveys this week</p><div class="weekly-progress"><div class="weekly-progress-fill" style="width:${wPct}%"></div></div><div class="weekly-progress-label"><span>${wCount} / ${wGoal}</span><span>${wPct.toFixed(0)}%</span></div></div>`;const ws=readStore(STORE_WITHDRAWALS,[]).filter(w=>w.user_id===currentUser.id).sort((a,b)=>(b.created_at||0)-(a.created_at||0));const wsHTML=ws.length>0?`<div class="wallet-transactions" style="margin-top:20px;"><h3>Withdrawal History</h3><div class="transaction-list">${ws.slice(0,10).map(w=>{const ml=w.method==='crypto'?'USDT BEP20':'M-Pesa';const dest=w.method==='crypto'?w.usdt_address:w.phone;const short=dest?dest.slice(0,12)+'...'+dest.slice(-6):'';const ic=w.status==='completed'?'approved':(w.status==='rejected'?'rejected':'pending');return `<div class="transaction-item"><div class="transaction-icon ${ic}"><svg><use href="${w.status==='completed'?'#i-check-circle':(w.status==='rejected'?'#i-x-circle':'#i-clock')}"/></svg></div><div class="transaction-info"><strong>${ml} — ${escapeHtml(short)}</strong><small>${new Date(w.created_at).toLocaleDateString()} · ${w.status}</small></div><div class="transaction-amount ${ic}">KSh ${w.amount}</div></div>`;}).join('')}</div></div>`:'';const txs=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===currentUser.id).map(p=>{const s=ss.find(x=>x.id===p.survey_id);const r=s?(s.reward||20):20;let stat=p.review_status||'pending';if(stat==='reviewed'||stat==='in_progress')stat='pending';if(p.review_status==='screened_out'||p.status==='screened_out')stat='rejected';return {id:p.id,title:s?s.title:'Deleted',date:p.submitted_at||p.updated_at,amount:stat==='approved'?r:(stat==='pending'?r:0),status:stat};}).sort((a,b)=>b.date-a.date);const txHTML=txs.length===0?'<div class="state-box"><strong>No transactions</strong></div>':'<div class="transaction-list">'+txs.map(t=>{const ic=t.status==='approved'?'i-check-circle':(t.status==='rejected'?'i-x-circle':'i-clock');const am=t.status==='rejected'?'<div class="transaction-amount rejected">KSh 0</div>':`<div class="transaction-amount ${t.status}">+ KSh ${t.amount}</div>`;return `<div class="transaction-item"><div class="transaction-icon ${t.status}"><svg><use href="#${ic}"/></svg></div><div class="transaction-info"><strong>${escapeHtml(t.title)}</strong><small>${new Date(t.date).toLocaleDateString()} · ${t.status}</small></div>${am}</div>`;}).join('')+'</div>';c.innerHTML=`<div class="wallet-header"><h2>Wallet</h2><p>Your earnings, all in one place.</p></div><div style="display:flex;justify-content:center;margin-bottom:18px;"><span class="profile-tier-badge tier-${tier}"><svg style="width:14px;height:14px;"><use href="#${plan.icon}"/></svg>${plan.label}</span></div>${streakHTML}${weeklyHTML}<div class="wallet-summary-row"><div class="wallet-summary-tile primary"><span class="wst-label">Current Balance</span><span class="wst-value">KSh ${current.toLocaleString()}</span><span class="wst-sub">Available to withdraw</span>${canWithdraw?'<span class="wst-badge">✓ Ready</span>':''}</div><div class="wallet-summary-tile"><span class="wst-label">Lifetime Earned</span><span class="wst-value">KSh ${lifetime.toLocaleString()}</span><span class="wst-sub">All time (surveys + bonuses)</span></div></div><div class="wallet-balance-card"><div class="wallet-balance-label">Withdrawal Progress</div><div class="wallet-progress-box"><div class="wallet-progress-top"><span>${canWithdraw?'Unlocked':'Progress'}</span><span>KSh ${current.toLocaleString()} / ${threshold.toLocaleString()}</span></div><div class="wallet-progress-bar"><div class="wallet-progress-fill" style="width:${progress}%"></div></div><div class="wallet-progress-hint">${canWithdraw?'✓ You can withdraw now':'KSh '+remaining.toLocaleString()+' more to unlock'}</div></div>${canWithdraw?`<button class="btn btn-light wallet-withdraw-btn" onclick="openWithdrawalModal()"><svg style="width:16px;height:16px;"><use href="#i-download"/></svg>Withdraw KSh ${current.toLocaleString()}</button>`:'<button class="btn btn-light wallet-withdraw-btn" disabled style="opacity:.65;"><svg style="width:16px;height:16px;"><use href="#i-lock"/></svg>Withdraw (locked)</button>'}</div>${daily?`<div class="daily-limits-card"><div class="daily-limits-header"><h3>Today\'s Activity</h3><small>Resets midnight</small></div><div class="daily-limit-row"><div class="daily-limit-labels"><span>Surveys</span><span>${daily.surveyCount} / ${daily.surveyLimit}</span></div><div class="daily-limit-bar"><div class="daily-limit-fill ${sp>=100?'full':sp>=66?'warn':''}" style="width:${sp}%"></div></div></div><div class="daily-limit-row"><div class="daily-limit-labels"><span>Earned today</span><span>KSh ${daily.totalRewards} / KSh ${daily.earningsCap}</span></div><div class="daily-limit-bar"><div class="daily-limit-fill ${ep>=100?'full':ep>=66?'warn':''}" style="width:${ep}%"></div></div></div></div>`:''}<div class="wallet-stats-row"><div class="wallet-stat-tile"><span class="val">KSh ${current.toLocaleString()}</span><span class="lbl">Available</span></div><div class="wallet-stat-tile"><span class="val">KSh ${pending.toLocaleString()}</span><span class="lbl">Pending review</span></div></div><div class="wallet-transactions"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px;"><h3 style="margin:0;">Recent Activity</h3><button class="btn btn-outline btn-sm" onclick="navigate(\'history\')">View History →</button></div>${txHTML}</div><div style="margin-top:20px;"><div class="promo-redeem-row"><input type="text" id="promo-input" placeholder="Enter promo code" maxlength="15"><button class="btn btn-primary" onclick="redeemPromo()">Redeem</button></div></div>${wsHTML}`;}

function openWithdrawalModal(){if(!currentUser)return;const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===currentUser.id);const plan=PLANS[u.tier||'basic'];const bal=getUserBalance(currentUser.id);document.getElementById('withdraw-phone').value=u.phone||'';document.getElementById('withdraw-usdt').value=u.usdtAddress||'';document.getElementById('withdraw-amount').value='';const hint=document.getElementById('withdraw-hint');if(hint)hint.innerHTML=`Available: <strong>KSh ${bal.available.toLocaleString()}</strong> · Minimum: <strong>KSh ${plan.withdrawalMin.toLocaleString()}</strong>`;document.getElementById('withdraw-notice').className='notice';selectWithdrawMethod('mpesa');document.getElementById('withdrawal-overlay').classList.add('open');}
function selectWithdrawMethod(method){withdrawMethod=method;document.querySelectorAll('.method-btn').forEach(b=>{if(b.dataset.method===method)b.classList.add('active');else b.classList.remove('active');});document.getElementById('withdraw-mpesa-fields').classList.toggle('hidden',method!=='mpesa');document.getElementById('withdraw-crypto-fields').classList.toggle('hidden',method!=='crypto');}
function closeWithdrawalModal(){document.getElementById('withdrawal-overlay').classList.remove('open');}
function handleWithdrawalOverlayClick(e){if(e.target.id==='withdrawal-overlay')closeWithdrawalModal();}
function submitWithdrawal(){const amount=parseInt(document.getElementById('withdraw-amount').value,10);const noticeEl=document.getElementById('withdraw-notice');try{const us=readStore(STORE_USERS,[]);const ui=us.findIndex(x=>x.id===currentUser.id);if(ui===-1)throw new Error('User not found');const plan=PLANS[us[ui].tier||'basic'];const bal=getUserBalance(currentUser.id);if(isNaN(amount)||amount<=0)throw new Error('Enter a valid amount.');if(amount>bal.available)throw new Error('Amount exceeds available balance.');if(amount<plan.withdrawalMin)throw new Error('Minimum KSh '+plan.withdrawalMin+' on '+plan.label+'.');const wd={id:uid('wd'),user_id:currentUser.id,amount:amount,status:'pending',created_at:Date.now(),updated_at:Date.now()};if(withdrawMethod==='mpesa'){const phone=document.getElementById('withdraw-phone').value.trim().replace(/\s/g,'');if(!/^0[17]\d{8}$/.test(phone))throw new Error('Enter valid M-Pesa (07XX or 01XX).');wd.method='mpesa';wd.phone=phone;us[ui].phone=phone;}else{const addr=document.getElementById('withdraw-usdt').value.trim();if(!/^0x[a-fA-F0-9]{40}$/.test(addr))throw new Error('Invalid USDT BEP20 address. Must start with 0x and be 42 chars.');wd.method='crypto';wd.usdt_address=addr;us[ui].usdtAddress=addr;}const wds=readStore(STORE_WITHDRAWALS,[]);wds.push(wd);writeStore(STORE_WITHDRAWALS,wds);writeStore(STORE_USERS,us);closeWithdrawalModal();showToast('Withdrawal request submitted!');renderWallet();}catch(e){noticeEl.className='notice show error';noticeEl.textContent=e.message;}}

function redeemPromo(){const i=document.getElementById('promo-input');if(!i)return;const code=i.value.trim().toUpperCase();if(!code){showToast('Enter code');return;}const ps=readStore(STORE_PROMOS,[]);const p=ps.find(x=>x.code===code);if(!p){showToast('Invalid code');return;}if((p.uses||[]).includes(currentUser.id)){showToast('Already redeemed');return;}if(p.maxUses&&(p.uses||[]).length>=p.maxUses){showToast('Code expired');return;}p.uses=p.uses||[];p.uses.push(currentUser.id);writeStore(STORE_PROMOS,ps);const us=readStore(STORE_USERS,[]);const ui=us.findIndex(x=>x.id===currentUser.id);us[ui].bonuses=us[ui].bonuses||[];us[ui].bonuses.push({id:uid('bon'),amount:p.amount,type:'promo',description:'Promo: '+code,created_at:Date.now()});writeStore(STORE_USERS,us);i.value='';showToast('🎉 KSh '+p.amount+' credited!');renderWallet();}

function renderHistory(){const c=document.getElementById('history-content');if(!currentUser){c.innerHTML='<div class="notif-empty"><div class="notif-empty-icon"><svg><use href="#i-list"/></svg></div><h3>Sign in</h3><button class="btn btn-primary" onclick="openAuth(\'signin\')" style="margin-top:16px;">Sign In</button></div>';return;}const ps=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===currentUser.id);const ss=readStore(STORE_SURVEYS,[]);const mapped=ps.map(p=>{const s=ss.find(x=>x.id===p.survey_id);let st=p.review_status||'pending';if(p.status==='screened_out'||p.review_status==='screened_out')st='screened_out';else if(p.status==='in_progress')st='in_progress';else if(p.status==='started')st='in_progress';else if(p.review_status==='reviewed')st='pending';const qt=s&&s.questions?s.questions.length:0;const qd=p.wizard_index||0;return {id:p.id,survey:s,title:s?s.title:'Deleted',status:st,reward:s?(s.reward||0):0,date:p.submitted_at||p.updated_at||p.started_at,progress:qt>0?Math.round((qd/qt)*100):100,qTotal:qt,surveyId:p.survey_id};}).sort((a,b)=>(b.date||0)-(a.date||0));const counts={all:mapped.length,in_progress:0,pending:0,approved:0,rejected:0,screened_out:0};mapped.forEach(m=>{if(counts[m.status]!==undefined)counts[m.status]++;});let f=historyFilter==='all'?mapped:mapped.filter(m=>m.status===historyFilter);let h='<div class="history-page"><div class="history-header"><h2>Survey History</h2><p>Every survey you took or started</p></div><div class="history-filters"><button class="history-filter '+(historyFilter==='all'?'active':'')+'" onclick="setHistoryFilter(\'all\')">All <span class="count">'+counts.all+'</span></button><button class="history-filter '+(historyFilter==='in_progress'?'active':'')+'" onclick="setHistoryFilter(\'in_progress\')">In Progress <span class="count">'+counts.in_progress+'</span></button><button class="history-filter '+(historyFilter==='pending'?'active':'')+'" onclick="setHistoryFilter(\'pending\')">Submitted <span class="count">'+counts.pending+'</span></button><button class="history-filter '+(historyFilter==='approved'?'active':'')+'" onclick="setHistoryFilter(\'approved\')">Approved <span class="count">'+counts.approved+'</span></button><button class="history-filter '+(historyFilter==='rejected'?'active':'')+'" onclick="setHistoryFilter(\'rejected\')">Rejected <span class="count">'+counts.rejected+'</span></button><button class="history-filter '+(historyFilter==='screened_out'?'active':'')+'" onclick="setHistoryFilter(\'screened_out\')">Screened <span class="count">'+counts.screened_out+'</span></button></div>';if(f.length===0)h+='<div class="state-box"><strong>Nothing here</strong></div>';else{h+='<div class="history-list">';f.forEach(m=>{const sl={in_progress:'In Progress',pending:'Under Review',approved:'Approved',rejected:'Rejected',screened_out:'Screened Out'}[m.status]||m.status;const ds=m.date?new Date(m.date).toLocaleDateString():'—';let btn=m.status==='in_progress'?`<button class="btn btn-primary btn-sm" onclick="navigate('take-survey','${m.surveyId}')">Continue →</button>`:`<button class="btn btn-outline btn-sm" onclick="navigate('detail','${m.surveyId}')">View</button>`;h+=`<div class="history-item"><div class="history-item-top"><strong>${escapeHtml(m.title)}</strong><span class="history-status ${m.status}">${sl}</span></div><div class="history-item-meta"><span><strong>KSh ${m.reward}</strong> reward</span><span>${ds}</span>${m.qTotal>0&&m.status==='in_progress'?`<span>${Math.round((m.progress/100)*m.qTotal)} / ${m.qTotal} questions</span>`:''}</div>${m.status==='in_progress'&&m.qTotal>0?`<div class="history-progress"><div class="history-progress-fill" style="width:${m.progress}%"></div></div>`:''}<div class="history-actions">${btn}</div></div>`;});h+='</div>';}h+='</div>';c.innerHTML=h;}
function setHistoryFilter(f){historyFilter=f;renderHistory();}

function renderProfile(){const c=document.getElementById('profile-content');if(!currentUser){c.innerHTML='<div class="profile-card"><div class="profile-avatar-container guest"><span class="initial">?</span></div><h2>Welcome to SurveyKE</h2><p class="profile-description">Sign in or create account.</p><div class="profile-actions"><button class="btn btn-primary btn-block" onclick="openAuth(\'signin\')">Sign In</button><button class="btn btn-outline btn-block" onclick="openAuth(\'signup\')">Create Account</button></div></div>';return;}const us=readStore(STORE_USERS,[]);const st=us.find(u=>u.id===currentUser.id)||{};const av=st.avatar||null;const refs=st.referrals||[];const code=st.referralCode||ensureReferralCode(st);const tier=st.tier||'basic';const plan=PLANS[tier];const parts=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===currentUser.id);const app=parts.filter(p=>p.review_status==='approved').length;const init=(currentUser.name||currentUser.email||'?').charAt(0).toUpperCase();const avH=av?`<img src="${escapeHtml(av)}" alt="">`:`<span class="initial">${escapeHtml(init)}</span>`;const uc=getUnreadNotificationsCount();const achs=st.achievements||[];const sd=st.streak?st.streak.days:0;const notifLink=`<button class="profile-notif-link" onclick="navigate('notifications')"><span class="profile-notif-link-left"><svg><use href="#i-bell"/></svg><span>Notifications</span></span>${uc>0?`<span class="badge">${uc}</span>`:'<svg style="width:16px;height:16px;color:var(--muted);"><use href="#i-chevron-right"/></svg>'}</button>`;const histLink=`<button class="profile-notif-link" onclick="navigate('history')"><span class="profile-notif-link-left"><svg><use href="#i-list"/></svg><span>Survey History</span></span><svg style="width:16px;height:16px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button>`;const achsH=`<div class="user-detail-section"><h4>🏆 Achievements (${achs.length}/${Object.keys(ACHIEVEMENTS).length})</h4><div class="achievements-grid">${Object.keys(ACHIEVEMENTS).map(k=>{const a=ACHIEVEMENTS[k];const u=achs.includes(k);return `<div class="achievement-chip ${u?'unlocked':''}"><span class="achievement-icon">${a.icon}</span><span class="achievement-name">${a.label}</span></div>`;}).join('')}</div></div>`;const strH=sd>0?`<div class="streak-display"><div class="streak-icon">🔥</div><div class="streak-info"><strong>Day ${sd} streak</strong><small>Daily bonus credited</small></div></div>`:'';let tierH='',statH='',planAct='',refH='';if(isAdmin){tierH='<div class="admin-badge">🔑 Administrator</div>';planAct='<button class="btn btn-primary btn-block" onclick="navigate(\'admin\')">Admin Dashboard</button>';}else{tierH=`<span class="profile-tier-badge tier-${tier}"><svg style="width:14px;height:14px;"><use href="#${plan.icon}"/></svg>${plan.label}</span>`;statH=`<div class="profile-stats"><div class="profile-stat"><span class="profile-stat-val">${parts.length}</span><span class="profile-stat-label">Surveys</span></div><div class="profile-stat"><span class="profile-stat-val">${app}</span><span class="profile-stat-label">Approved</span></div></div>`;planAct=`<button class="btn btn-outline btn-block" onclick="openPlanModal()"><svg style="width:16px;height:16px;"><use href="#i-crown"/></svg>Change Plan</button>`;refH=`<div class="referral-card"><div class="referral-header"><svg><use href="#i-gift"/></svg><strong>Referral Programme</strong></div><p class="referral-desc">Earn KSh 20 when a friend's first survey is approved.</p><div class="referral-code-box"><span class="referral-code-label">Your code</span><span class="referral-code-val">${escapeHtml(code)}</span></div><div class="referral-stats"><div class="referral-stat"><strong>${refs.length}</strong><small>Friends invited</small></div></div><div class="referral-actions"><button class="btn btn-outline btn-sm" onclick="copyReferralLink()"><svg style="width:14px;height:14px;"><use href="#i-copy"/></svg>Copy</button><button class="btn btn-outline btn-sm" onclick="shareReferralLink()"><svg style="width:14px;height:14px;"><use href="#i-share"/></svg>Share</button></div></div>`;}c.innerHTML=`<div class="profile-card"><div class="profile-avatar-container">${avH}</div><h2>${escapeHtml(currentUser.name||'User')}</h2><p class="profile-email">@${escapeHtml(currentUser.username||'user')} · ${escapeHtml(currentUser.email)}</p>${tierH}${statH}${strH}${notifLink}${histLink}${achsH}<div class="profile-actions"><button class="btn btn-primary btn-block" onclick="openEditProfile()"><svg style="width:16px;height:16px;"><use href="#i-edit"/></svg>Edit Profile</button>${planAct}</div>${refH}<div class="profile-actions"><button class="btn btn-outline btn-block" onclick="navigate(\'settings\')"><svg style="width:16px;height:16px;"><use href="#i-settings"/></svg>Settings</button><button class="btn btn-outline btn-block" onclick="signOut()">Sign Out</button></div><div class="danger-zone"><button class="btn btn-outline btn-block danger-btn" onclick="deleteAccount()"><svg style="width:16px;height:16px;"><use href="#i-trash"/></svg>Delete Account</button></div></div>`;updateNotifBadges();}
function openEditProfile(){if(!currentUser)return;const us=readStore(STORE_USERS,[]);const s=us.find(u=>u.id===currentUser.id)||{};editingAvatar=s.avatar||null;editingName=s.name||currentUser.name||'';document.getElementById('edit-name-input').value=editingName;document.getElementById('edit-profile-overlay').classList.add('open');document.getElementById('edit-profile-notice').className='notice';renderAvatarGrid();updateEditAvatarPreview();document.getElementById('edit-name-input').oninput=function(){editingName=this.value;if(!editingAvatar)updateEditAvatarPreview();};}
function closeEditProfile(){document.getElementById('edit-profile-overlay').classList.remove('open');}
function handleEditProfileOverlayClick(e){if(e.target.id==='edit-profile-overlay')closeEditProfile();}
function renderAvatarGrid(){const g=document.getElementById('avatar-grid');if(!g)return;g.innerHTML=ANIME_URLS.map(url=>`<button class="avatar-option ${editingAvatar===url?'selected':''}" onclick="selectAvatar('${url}')"><img src="${url}" loading="lazy"></button>`).join('');}
function selectAvatar(u){editingAvatar=u;renderAvatarGrid();updateEditAvatarPreview();}
function updateEditAvatarPreview(){const p=document.getElementById('edit-avatar-preview');if(!p)return;if(editingAvatar)p.innerHTML=`<img src="${escapeHtml(editingAvatar)}">`;else{const i=(editingName||(currentUser&&currentUser.email)||'?').charAt(0).toUpperCase();p.innerHTML=`<span class="initial">${escapeHtml(i)}</span>`;}}
function handleAvatarFileChange(e){const f=e.target.files[0];if(!f)return;if(f.size>2097152){showToast('Max 2MB');return;}const r=new FileReader();r.onload=ev=>{editingAvatar=ev.target.result;renderAvatarGrid();updateEditAvatarPreview();};r.readAsDataURL(f);}
function saveProfileEdits(){if(!currentUser)return;const n=document.getElementById('edit-name-input').value.trim();if(n.length<2){const e=document.getElementById('edit-profile-notice');e.className='notice show error';e.textContent='Name too short.';return;}const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;us[i].name=n;us[i].avatar=editingAvatar;writeStore(STORE_USERS,us);currentUser.name=n;currentUser.avatar=editingAvatar;closeEditProfile();showToast('Saved');renderProfile();updateAuthUI();}

function openPlanModal(){if(isAdmin||!currentUser)return;const us=readStore(STORE_USERS,[]);const s=us.find(u=>u.id===currentUser.id)||{};selectedPlan=s.tier||'basic';document.getElementById('plan-overlay').classList.add('open');document.getElementById('plan-notice').className='notice';document.querySelectorAll('.plan-card').forEach(c=>{const p=c.dataset.plan;c.classList.remove('selected','current');if(p===s.tier)c.classList.add('current');if(p===selectedPlan)c.classList.add('selected');let b=c.querySelector('.plan-badge-current');if(p===s.tier&&!b){b=document.createElement('div');b.className='plan-badge-current';b.textContent='Current';c.appendChild(b);}else if(p!==s.tier&&b)b.remove();});}
function closePlanModal(){document.getElementById('plan-overlay').classList.remove('open');}
function handlePlanOverlayClick(e){if(e.target.id==='plan-overlay')closePlanModal();}
function selectPlan(p){selectedPlan=p;document.querySelectorAll('.plan-card').forEach(c=>c.classList.toggle('selected',c.dataset.plan===p));}
function confirmPlanChange(){if(!currentUser||!selectedPlan)return;const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);if(i===-1)return;us[i].tier=selectedPlan;writeStore(STORE_USERS,us);currentUser.tier=selectedPlan;closePlanModal();showToast('Plan: '+PLANS[selectedPlan].label);if(currentView==='profile')renderProfile();if(currentView==='wallet')renderWallet();if(currentView==='settings')renderSettings();fetchAndRenderSurveys();checkAchievements();}

function renderSettings(){const c=document.getElementById('settings-content');const th=document.documentElement.getAttribute('data-theme')||'light';const n=readStore(STORE_NOTIFICATIONS,true);const tier=getUserTier();const plan=PLANS[tier];const us=readStore(STORE_USERS,[]);const st=currentUser?us.find(u=>u.id===currentUser.id):null;const lg=st?(st.logins||[]):[];const lgH=lg.length>0?`<div class="settings-group"><div class="settings-group-title">Login History</div><div style="background:var(--card);border:1px solid var(--line-strong);border-radius:14px;padding:8px 16px;">${lg.slice(-5).reverse().map(l=>`<div style="padding:8px 0;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted);"><strong style="color:var(--ink);">${new Date(l.time).toLocaleString()}</strong><br>${escapeHtml((l.ua||'Unknown').slice(0,80))}</div>`).join('')}</div></div>`:'';c.innerHTML=`<div class="settings-container"><div class="settings-header"><h2>Settings</h2><p>Manage your preferences</p></div><div class="settings-group"><div class="settings-group-title">Appearance</div><div class="settings-item"><div class="settings-item-left"><strong>Theme</strong><small>Light or dark</small></div><div class="theme-selector"><button class="theme-option ${th==='light'?'active':''}" onclick="setTheme('light')">Light</button><button class="theme-option ${th==='dark'?'active':''}" onclick="setTheme('dark')">Dark</button></div></div></div><div class="settings-group"><div class="settings-group-title">Notifications</div><div class="settings-item"><div class="settings-item-left"><strong>Email Notifications</strong><small>Get notified</small></div><button class="toggle-switch ${n?'on':''}" onclick="toggleNotifications()"><span class="toggle-knob"></span></button></div></div>${currentUser?'<div class="settings-group"><div class="settings-group-title">Account</div><button class="settings-item settings-item-btn" onclick="navigate(\'profile\')"><div class="settings-item-left"><strong>Profile</strong><small>Edit name, avatar</small></div><svg style="width:18px;height:18px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button><button class="settings-item settings-item-btn" onclick="openPasswordModal()"><div class="settings-item-left"><strong>Change Password</strong></div><svg style="width:18px;height:18px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button>'+(isAdmin?'':`<button class="settings-item settings-item-btn" onclick="openPlanModal()"><div class="settings-item-left"><strong>Change Plan</strong><small>Current: ${plan.label}</small></div><svg style="width:18px;height:18px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button>`)+'</div>':''}${lgH}<div class="settings-group"><div class="settings-group-title">Privacy &amp; Data</div><div class="settings-item"><div class="settings-item-left"><strong>Clear App Data</strong><small>Remove everything</small></div><button class="btn btn-outline btn-sm" onclick="clearAppData()">Clear</button></div></div><div class="settings-group"><div class="settings-group-title">About</div><div class="settings-item settings-item-static"><div class="settings-item-left"><strong>SurveyKE</strong><small>v2.2 · Built for Kenya</small></div></div><button class="settings-item settings-item-btn" onclick="navigate(\'static\',\'terms\')"><div class="settings-item-left"><strong>Terms of Service</strong></div><svg style="width:18px;height:18px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button><button class="settings-item settings-item-btn" onclick="navigate(\'static\',\'privacy\')"><div class="settings-item-left"><strong>Privacy Policy</strong></div><svg style="width:18px;height:18px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button><button class="settings-item settings-item-btn" onclick="navigate(\'static\',\'faq\')"><div class="settings-item-left"><strong>FAQ</strong><small>Common questions</small></div><svg style="width:18px;height:18px;color:var(--muted);"><use href="#i-chevron-right"/></svg></button></div>${currentUser?'<div class="settings-group"><div class="settings-group-title">Danger Zone</div><div class="settings-item"><div class="settings-item-left"><strong>Delete Account</strong><small>Permanently remove</small></div><button class="btn btn-outline btn-sm danger-btn" onclick="deleteAccount()">Delete</button></div></div>':''}</div>`;}
function toggleNotifications(){const c=readStore(STORE_NOTIFICATIONS,true);writeStore(STORE_NOTIFICATIONS,!c);renderSettings();}
function clearAppData(){if(!confirm('Clear all data? You will be logged out.'))return;[STORE_USERS,STORE_SESSION,STORE_SURVEYS,STORE_PARTICIPATIONS,STORE_RESPONSES,STORE_PENDING_REF,STORE_NOTIFICATIONS,STORE_WITHDRAWALS,STORE_PROMOS].forEach(k=>localStorage.removeItem(k));location.reload();}
function deleteAccount(){if(!currentUser)return;if(!confirm('Delete account permanently?'))return;const id=currentUser.id;let us=readStore(STORE_USERS,[]);us=us.filter(u=>u.id!==id);us.forEach(u=>{if(u.referrals)u.referrals=u.referrals.filter(x=>x!==id);});writeStore(STORE_USERS,us);let p=readStore(STORE_PARTICIPATIONS,[]);p=p.filter(x=>x.user_id!==id);writeStore(STORE_PARTICIPATIONS,p);let r=readStore(STORE_RESPONSES,[]);r=r.filter(x=>x.user_id!==id);writeStore(STORE_RESPONSES,r);let w=readStore(STORE_WITHDRAWALS,[]);w=w.filter(x=>x.user_id!==id);writeStore(STORE_WITHDRAWALS,w);writeStore(STORE_SESSION,null);currentUser=null;isAdmin=false;updateAuthUI();navigate('home');showToast('Deleted.');}
function openPasswordModal(){document.getElementById('password-overlay').classList.add('open');document.getElementById('old-password').value='';document.getElementById('new-password').value='';document.getElementById('password-notice').className='notice';}
function closePasswordModal(){document.getElementById('password-overlay').classList.remove('open');}
function handlePasswordOverlayClick(e){if(e.target.id==='password-overlay')closePasswordModal();}
async function changePassword(){const op=document.getElementById('old-password').value;const np=document.getElementById('new-password').value;const n=document.getElementById('password-notice');try{if(!currentUser)throw new Error('Not signed in');if(np.length<6)throw new Error('New password 6+ chars');const us=readStore(STORE_USERS,[]);const i=us.findIndex(u=>u.id===currentUser.id);const oh=await hashPassword(op);if(us[i].passwordHash!==oh)throw new Error('Current password incorrect');us[i].passwordHash=await hashPassword(np);writeStore(STORE_USERS,us);closePasswordModal();showToast('Password updated!');}catch(e){n.className='notice show error';n.textContent=e.message;}}

const STATIC_PAGES={faq:{title:'FAQ',html:'<div class="faq-item"><div class="faq-question" onclick="toggleFaq(this)">When do I get paid?<svg style="width:16px;height:16px;" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></div><div class="faq-answer">Approved surveys appear in your wallet immediately. Withdrawals process within 24-48 hours to M-Pesa or USDT BEP20.</div></div><div class="faq-item"><div class="faq-question" onclick="toggleFaq(this)">Why was I rejected?<svg style="width:16px;height:16px;" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></div><div class="faq-answer">Answers are reviewed for consistency. Rushed or duplicated answers may be rejected.</div></div><div class="faq-item"><div class="faq-question" onclick="toggleFaq(this)">What is screening out?<svg style="width:16px;height:16px;" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></div><div class="faq-answer">Some surveys have qualifying questions. Wrong answers screen you out. No reward is given.</div></div><div class="faq-item"><div class="faq-question" onclick="toggleFaq(this)">How do tiers work?<svg style="width:16px;height:16px;" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></div><div class="faq-answer">Basic is free (3 surveys/day, KSh 50). Silver: 5/day KSh 100. Gold: 8/day KSh 200. Platinum: 10/day KSh 300 with the lowest withdrawal minimum.</div></div><div class="faq-item"><div class="faq-question" onclick="toggleFaq(this)">Withdrawal methods?<svg style="width:16px;height:16px;" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></div><div class="faq-answer">M-Pesa (Kenya mobile money) and USDT BEP20 (Binance Smart Chain). Choose at withdrawal time.</div></div><div class="faq-item"><div class="faq-question" onclick="toggleFaq(this)">Is my data safe?<svg style="width:16px;height:16px;" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></div><div class="faq-answer">All data is stored locally in your browser. Nothing is sent to servers.</div></div>'},terms:{title:'Terms of Service',html:'<p>Last updated: '+new Date().toLocaleDateString()+'</p><h2>1. Acceptance</h2><p>By using SurveyKE you agree to these terms.</p><h2>2. Eligibility</h2><p>18+ and Kenyan resident.</p><h2>3. Account</h2><p>One account per person. You are responsible for your password.</p><h2>4. Surveys</h2><p>Answer honestly. False answers may result in rejection.</p><h2>5. Rewards</h2><p>Credited after admin approval. Screening out is not eligible.</p><h2>6. Withdrawals</h2><p>M-Pesa and USDT BEP20 only. Minimums vary by plan. Processed within 24-48 hours.</p><h2>7. Prohibited</h2><p>Bots, fabricated data, hacking, referral abuse are prohibited.</p><h2>8. Contact</h2><p>facelessdime@gmail.com</p>'},privacy:{title:'Privacy Policy',html:'<p>Last updated: '+new Date().toLocaleDateString()+'</p><h2>1. Data We Store</h2><p>Your account data and survey answers are stored <strong>locally in your browser</strong> using localStorage.</p><h2>2. What We Do NOT Do</h2><p>We do not send data to servers, track you, use advertising cookies, or sell your data.</p><h2>3. Data Retention</h2><p>Data remains on your device until you delete your account or clear browser data.</p><h2>4. Your Rights</h2><p>View, edit, or delete all your data at any time through Settings.</p><h2>5. Security</h2><p>Passwords hashed with SHA-256. Use strong unique passwords.</p><h2>6. Contact</h2><p>facelessdime@gmail.com</p>'}};
function renderStaticPage(p){const c=document.getElementById('static-content');const ct=STATIC_PAGES[p];if(!ct){c.innerHTML='<div class="state-box"><strong>Not found</strong></div>';return;}c.innerHTML=`<div class="static-page"><a href="#" class="back-link" onclick="navigate('home');return false;"><svg><use href="#i-arrow"/></svg>Back</a><h1>${ct.title}</h1>${ct.html}</div>`;}
function toggleFaq(el){el.parentElement.classList.toggle('open');}

function switchAdminSection(s){adminSection=s;document.querySelectorAll('.admin-subtab').forEach(b=>{if(b.dataset.section===s)b.classList.add('active');else b.classList.remove('active');});document.querySelectorAll('.admin-section').forEach(sec=>{if(sec.id==='admin-section-'+s)sec.classList.remove('hidden');else sec.classList.add('hidden');});if(s==='manage')loadAdminSurveysTable();if(s==='review')loadAdminParticipationsTable();if(s==='withdrawals')loadAdminWithdrawals();if(s==='promos')loadAdminPromos();}
function setAdminSurveyType(t){adminSurveyType=t;document.querySelectorAll('.admin-type-btn').forEach(b=>{if(b.dataset.type===t)b.classList.add('active');else b.classList.remove('active');});document.getElementById('admin-external-fields').classList.toggle('hidden',t!=='external');document.getElementById('admin-internal-fields').classList.toggle('hidden',t!=='internal');const u=document.getElementById('admin-url');if(u)u.required=(t==='external');if(t==='internal'&&adminQuestions.length===0)addAdminQuestion();}
function addAdminQuestion(){adminQuestions.push({id:uid('q'),type:'mcq',question:'',options:['',''],required:true,screenOut:false,correctOptions:[]});renderAdminQuestions();}
function removeAdminQuestion(id){adminQuestions=adminQuestions.filter(q=>q.id!==id);renderAdminQuestions();}
function updateAdminQuestion(id,f,v){const q=adminQuestions.find(x=>x.id===id);if(q)q[f]=v;}
function updateAdminQuestionOption(id,i,v){const q=adminQuestions.find(x=>x.id===id);if(q&&q.options)q.options[i]=v;}
function addQuestionOption(id){const q=adminQuestions.find(x=>x.id===id);if(q){q.options.push('');renderAdminQuestions();}}
function removeQuestionOption(id,i){const q=adminQuestions.find(x=>x.id===id);if(q&&q.options.length>2){q.options.splice(i,1);q.correctOptions=q.correctOptions.filter(x=>x!==i).map(x=>x>i?x-1:x);renderAdminQuestions();}}
function changeQuestionType(id,t){const q=adminQuestions.find(x=>x.id===id);if(!q)return;q.type=t;if(t==='mcq'&&(!q.options||q.options.length<2))q.options=['',''];if(t!=='mcq'){q.screenOut=false;q.correctOptions=[];}renderAdminQuestions();}
function toggleAdminScreenOut(id,c){const q=adminQuestions.find(x=>x.id===id);if(q){q.screenOut=c;if(!c)q.correctOptions=[];renderAdminQuestions();}}
function toggleCorrectOption(id,i){const q=adminQuestions.find(x=>x.id===id);if(!q)return;q.correctOptions=q.correctOptions||[];const idx=q.correctOptions.indexOf(i);if(idx===-1)q.correctOptions.push(i);else q.correctOptions.splice(idx,1);renderAdminQuestions();}
function renderAdminQuestions(){const w=document.getElementById('admin-questions-list');if(!w)return;if(adminQuestions.length===0){w.innerHTML='<p style="font-size:12px;color:var(--muted);text-align:center;padding:14px 0;">No questions.</p>';return;}w.innerHTML=adminQuestions.map((q,idx)=>{let h=`<div class="question-builder"><div class="question-builder-header"><strong>Q${idx+1}</strong><button type="button" class="qb-remove" onclick="removeAdminQuestion('${q.id}')">Remove</button></div><div class="qb-field"><label>Type</label><select onchange="changeQuestionType('${q.id}',this.value)"><option value="mcq"${q.type==='mcq'?' selected':''}>Multiple Choice</option><option value="text"${q.type==='text'?' selected':''}>Short Text</option><option value="paragraph"${q.type==='paragraph'?' selected':''}>Paragraph</option><option value="rating"${q.type==='rating'?' selected':''}>Rating</option></select></div><div class="qb-field"><label>Question</label><input type="text" value="${escapeHtml(q.question)}" oninput="updateAdminQuestion('${q.id}','question',this.value)"></div>`;if(q.type==='mcq'){h+=`<div class="qb-screenout-toggle"><input type="checkbox"${q.screenOut?' checked':''} onchange="toggleAdminScreenOut('${q.id}',this.checked)"><label>Screen-out<small>Wrong answers kick user</small></label></div><div class="qb-field"><label>Options${q.screenOut?' — ✓ correct':''}</label><div class="qb-options-list">`;q.options.forEach((opt,oi)=>{const c=(q.correctOptions||[]).indexOf(oi)!==-1;h+='<div class="qb-option-row">';if(q.screenOut)h+=`<label class="qb-opt-correct-label"><input type="checkbox"${c?' checked':''} onchange="toggleCorrectOption('${q.id}',${oi})">✓</label>`;h+=`<input type="text" value="${escapeHtml(opt)}" oninput="updateAdminQuestionOption('${q.id}',${oi},this.value)">`;if(q.options.length>2)h+=`<button type="button" class="qb-remove-opt" onclick="removeQuestionOption('${q.id}',${oi})">×</button>`;h+='</div>';});h+=`</div><button type="button" class="qb-add-option" onclick="addQuestionOption('${q.id}')" style="margin-top:8px;">+ Add Option</button></div>`;}h+=`<div class="qb-field"><div class="qb-required-row"><input type="checkbox"${q.required?' checked':''} onchange="updateAdminQuestion('${q.id}','required',this.checked)"><span>Required</span></div></div></div>`;return h;}).join('');}
async function renderAdminDashboard(){const u=document.getElementById('admin-unauthorized');const a=document.getElementById('admin-authorized');if(!isAdmin){u.classList.remove('hidden');a.classList.add('hidden');return;}u.classList.add('hidden');a.classList.remove('hidden');switchAdminSection(adminSection||'add');}
async function loadAdminSurveysTable(){const w=document.getElementById('admin-surveys-list-wrap');const all=readStore(STORE_SURVEYS,[]).slice().sort((a,b)=>(b.created_at||0)-(a.created_at||0));if(all.length===0){w.innerHTML='<p style="color:var(--muted);">No surveys.</p>';return;}w.innerHTML='<div style="overflow-x:auto;"><table class="admin-table"><thead><tr><th>Title</th><th>Type</th><th>Tier</th><th>Reward</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+all.map(s=>{const tt=s.status==='published'?'closed':'published';const pub=s.status==='published';const tl=s.type==='internal'?'📝':'🔗';const sl=s.type==='internal'?(s.questions?s.questions.length+' questions':''):(s.survey_url||'');const cls=pub?'admin-act-close':'admin-act-publish';const ic=pub?'i-lock':'i-check-circle';return `<tr><td><strong>${escapeHtml(s.title)}</strong><br><small style="color:var(--muted);">${escapeHtml(sl)}</small></td><td>${tl}</td><td>${tierBadgeHTML(s.tier)}</td><td>KSh ${s.reward||20}</td><td><span class="status-chip">${escapeHtml(s.status)}</span></td><td><button class="admin-act-btn ${cls}" onclick="toggleSurveyStatus('${s.id}','${tt}')"><svg><use href="#${ic}"/></svg>${pub?'Close':'Publish'}</button><button class="admin-act-btn admin-act-delete" onclick="deleteSurvey('${s.id}')"><svg><use href="#i-trash"/></svg>Delete</button></td></tr>`;}).join('')+'</tbody></table></div>';}
async function loadAdminParticipationsTable(){const w=document.getElementById('admin-participations-wrap');const all=readStore(STORE_PARTICIPATIONS,[]).slice().sort((a,b)=>(b.submitted_at||b.updated_at||0)-(a.submitted_at||a.updated_at||0));const ss=readStore(STORE_SURVEYS,[]),us=readStore(STORE_USERS,[]);const cnt={pending:0,reviewed:0,approved:0,rejected:0};all.forEach(p=>{const s=p.review_status||'pending';if(cnt[s]!==undefined)cnt[s]++;if(s==='screened_out')cnt.rejected++;});let h='<div class="admin-tabs">';['pending','reviewed','approved','rejected'].forEach(st=>{h+=`<button class="admin-tab ${adminParticipationTab===st?'active':''}" onclick="setAdminParticipationTab('${st}')">${st.charAt(0).toUpperCase()+st.slice(1)} <span class="count">${cnt[st]}</span></button>`;});h+='</div>';let f=adminParticipationTab==='rejected'?all.filter(p=>p.review_status==='rejected'||p.review_status==='screened_out'||p.status==='screened_out'):all.filter(p=>(p.review_status||'pending')===adminParticipationTab);if(f.length===0)h+=`<div class="state-box"><strong>No ${adminParticipationTab}</strong></div>`;else{h+='<div style="overflow-x:auto;"><table class="admin-table"><thead><tr><th>User</th><th>Survey</th><th>Type</th><th>Date</th><th>Actions</th></tr></thead><tbody>';f.forEach(p=>{const s=ss.find(x=>x.id===p.survey_id);const u=us.find(x=>x.id===p.user_id);const un=u?(u.name||u.email):'Unknown';const ue=u?('@'+(u.username||'')+' · '+u.email):'—';const tl=s&&s.type==='internal'?'📝':'🔗';const ds=(p.submitted_at||p.updated_at)?new Date(p.submitted_at||p.updated_at).toLocaleDateString():'—';const acts=renderParticipationActions(p,s&&s.type==='internal');h+=`<tr><td><a href="#" onclick="viewAdminUser('${u?u.id:''}');return false;" style="color:var(--green-dark);font-weight:700;text-decoration:underline;">${escapeHtml(un)}</a><br><small style="color:var(--muted);">${escapeHtml(ue)}</small></td><td><strong>${escapeHtml(s?s.title:'Deleted')}</strong></td><td>${tl}</td><td>${ds}</td><td>${acts}</td></tr>`;});h+='</tbody></table></div>';}w.innerHTML=h;}
function setAdminParticipationTab(t){adminParticipationTab=t;loadAdminParticipationsTable();}
function renderParticipationActions(p,isI){const st=p.review_status||'pending';const isS=st==='screened_out'||p.status==='screened_out';if(st==='approved'||st==='rejected'||isS)return `<span class="locked-badge"><svg><use href="#i-lock"/></svg>${isS?'Screened Out':(st.charAt(0).toUpperCase()+st.slice(1))}</span>`;let b=[];if(isI)b.push(`<button class="admin-act-btn admin-act-view" onclick="viewResponse('${p.id}')"><svg><use href="#i-book"/></svg>View</button>`);if(st==='pending')b.push(`<button class="admin-act-btn admin-act-review" onclick="markReviewed('${p.id}')"><svg><use href="#i-check"/></svg>Review</button>`);b.push(`<button class="admin-act-btn admin-act-approve" onclick="reviewParticipation('${p.id}','approved')"><svg><use href="#i-check-circle"/></svg>Approve</button>`);b.push(`<button class="admin-act-btn admin-act-delete" onclick="reviewParticipation('${p.id}','rejected')"><svg><use href="#i-x-circle"/></svg>Reject</button>`);return b.join('');}
function markReviewed(id){try{const ps=readStore(STORE_PARTICIPATIONS,[]);const i=ps.findIndex(p=>p.id===id);if(i===-1)throw new Error('Not found');const p=ps[i];if(p.review_status==='approved'||p.review_status==='rejected'||p.review_status==='screened_out')throw new Error('Finalized');p.review_status='reviewed';p.reviewed_at=Date.now();writeStore(STORE_PARTICIPATIONS,ps);showToast('Reviewed');loadAdminParticipationsTable();}catch(e){showToast(e.message);}}
async function reviewParticipation(id,dec){try{const ps=readStore(STORE_PARTICIPATIONS,[]);const i=ps.findIndex(p=>p.id===id);if(i===-1)throw new Error('Not found');const st=ps[i].review_status||'pending';if(st==='approved'||st==='rejected'||st==='screened_out')throw new Error('Finalized');ps[i].review_status=dec;ps[i].reviewed_at=Date.now();writeStore(STORE_PARTICIPATIONS,ps);if(dec==='approved'){const uid=ps[i].user_id;const app=ps.filter(p=>p.user_id===uid&&p.review_status==='approved');if(app.length===1){const us=readStore(STORE_USERS,[]);const au=us.find(u=>u.id===uid);if(au&&au.referred_by){const ri=us.findIndex(u=>(u.referralCode||'').toUpperCase()===au.referred_by);if(ri!==-1){us[ri].bonuses=us[ri].bonuses||[];us[ri].bonuses.push({id:uid('bon'),amount:20,type:'referral',description:'Referral: @'+au.username,created_at:Date.now()});writeStore(STORE_USERS,us);}}}}showToast(dec);await loadAdminParticipationsTable();}catch(e){showToast(e.message);}}
function viewResponse(id){const ps=readStore(STORE_PARTICIPATIONS,[]);const p=ps.find(x=>x.id===id);if(!p)return;const ss=readStore(STORE_SURVEYS,[]);const s=ss.find(x=>x.id===p.survey_id);if(!s||s.type!=='internal')return;const rs=readStore(STORE_RESPONSES,[]);const r=rs.find(x=>x.survey_id===s.id&&x.user_id===p.user_id);const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===p.user_id);if(p.review_status==='pending'){p.review_status='reviewed';p.reviewed_at=Date.now();const all=readStore(STORE_PARTICIPATIONS,[]);const ix=all.findIndex(x=>x.id===id);if(ix!==-1){all[ix].review_status='reviewed';all[ix].reviewed_at=p.reviewed_at;writeStore(STORE_PARTICIPATIONS,all);}}const c=document.getElementById('response-viewer-content');let h=`<h2 style="margin:0 0 6px;font-size:20px;">${escapeHtml(s.title)}</h2><div class="response-user-info"><strong>${escapeHtml(u?(u.name||u.email):'Unknown')}</strong><br>${u&&u.username?'@'+escapeHtml(u.username)+'<br>':''}${escapeHtml(u?u.email:'')}</div>`;if(!r)h+='<p style="color:var(--muted);text-align:center;">No answers.</p>';else{h+='<div class="response-list">';(s.questions||[]).forEach((q,i)=>{const a=r.answers?r.answers[q.id]:'';h+=`<div class="response-answer"><div class="response-answer-label">Q${i+1}</div><div class="response-answer-q">${escapeHtml(q.question)}</div><div class="response-answer-val">${escapeHtml(String(a)||'—')}</div></div>`;});h+='</div>';}const fin=p.review_status==='approved'||p.review_status==='rejected'||p.review_status==='screened_out';h+='<div class="modal-actions"><button class="btn btn-outline" onclick="closeResponseViewer()">Close</button>';if(!fin)h+=`<button class="btn btn-primary" onclick="closeResponseViewer();reviewParticipation('${p.id}','approved')">Approve</button><button class="btn btn-outline danger-btn" onclick="closeResponseViewer();reviewParticipation('${p.id}','rejected')">Reject</button>`;h+='</div>';c.innerHTML=h;document.getElementById('response-viewer-overlay').classList.add('open');loadAdminParticipationsTable();}
function closeResponseViewer(){document.getElementById('response-viewer-overlay').classList.remove('open');}
function handleResponseViewerOverlayClick(e){if(e.target.id==='response-viewer-overlay')closeResponseViewer();}

function viewAdminUser(userId){if(!isAdmin||!userId)return;const us=readStore(STORE_USERS,[]);const u=us.find(x=>x.id===userId);if(!u){showToast('Not found');return;}const ps=readStore(STORE_PARTICIPATIONS,[]).filter(p=>p.user_id===userId);const ss=readStore(STORE_SURVEYS,[]);const ws=readStore(STORE_WITHDRAWALS,[]).filter(w=>w.user_id===userId);const bal=getUserBalance(userId);const pw=ws.filter(w=>w.status==='pending'||w.status==='processing').reduce((s,w)=>s+w.amount,0);const app=ps.filter(p=>p.review_status==='approved').length;const init=(u.name||u.email||'?').charAt(0).toUpperCase();const avH=u.avatar?`<img src="${escapeHtml(u.avatar)}">`:escapeHtml(init);const c=document.getElementById('admin-user-content');let h=`<div class="user-detail-header"><div class="user-detail-avatar">${avH}</div><div class="user-detail-info"><h3>${escapeHtml(u.name||'User')}</h3><p>@${escapeHtml(u.username||'user')} · ${escapeHtml(u.email)}</p><p style="margin-top:4px;">Tier: <strong>${PLANS[u.tier||'basic'].label}</strong> · Referral: <strong>${escapeHtml(u.referralCode||'—')}</strong></p></div></div><div class="user-detail-stats"><div class="user-detail-stat"><span class="user-detail-stat-val">${ps.length}</span><span class="user-detail-stat-lbl">Surveys</span></div><div class="user-detail-stat"><span class="user-detail-stat-val">${app}</span><span class="user-detail-stat-lbl">Approved</span></div><div class="user-detail-stat"><span class="user-detail-stat-val">KSh ${bal.available.toLocaleString()}</span><span class="user-detail-stat-lbl">Available</span></div></div><div class="user-detail-section"><h4>Financial</h4><div class="user-detail-row"><span>Lifetime earned</span><span>KSh ${bal.lifetime.toLocaleString()}</span></div><div class="user-detail-row"><span>From surveys</span><span>KSh ${bal.earned.toLocaleString()}</span></div><div class="user-detail-row"><span>From bonuses</span><span>KSh ${bal.bonuses.toLocaleString()}</span></div><div class="user-detail-row"><span>Withdrawn</span><span>KSh ${bal.withdrawn.toLocaleString()}</span></div><div class="user-detail-row"><span>Pending withdrawals</span><span>KSh ${pw.toLocaleString()}</span></div></div>`;if(u.phone)h+=`<div class="user-detail-section"><h4>M-Pesa</h4><div class="user-detail-row"><span>Number</span><span>${escapeHtml(u.phone)}</span></div></div>`;if(u.usdtAddress)h+=`<div class="user-detail-section"><h4>USDT BEP20</h4><div class="user-detail-row"><span>Address</span><span style="font-family:monospace;font-size:11px;word-break:break-all;">${escapeHtml(u.usdtAddress)}</span></div></div>`;if(ps.length>0){h+='<div class="user-detail-section"><h4>Recent Participations</h4>';ps.sort((a,b)=>(b.submitted_at||0)-(a.submitted_at||0)).slice(0,10).forEach(p=>{const s=ss.find(x=>x.id===p.survey_id);h+=`<div class="user-detail-part"><span><strong>${escapeHtml(s?s.title:'Deleted')}</strong></span><span class="user-detail-part-status history-status ${p.review_status||'pending'}">${p.review_status||'pending'}</span></div>`;});h+='</div>';}h+='<div class="modal-actions"><button class="btn btn-outline" onclick="closeAdminUserModal()">Close</button></div>';c.innerHTML=h;document.getElementById('admin-user-overlay').classList.add('open');}
function closeAdminUserModal(){document.getElementById('admin-user-overlay').classList.remove('open');}
function handleAdminUserOverlayClick(e){if(e.target.id==='admin-user-overlay')closeAdminUserModal();}

async function handleCreateSurvey(e){e.preventDefault();const n=document.getElementById('admin-create-notice');const b=document.getElementById('admin-submit-btn');const t=document.getElementById('admin-title').value.trim();const cat=document.getElementById('admin-category').value;const d=document.getElementById('admin-description').value.trim();const dur=parseInt(document.getElementById('admin-duration').value,10);const rw=parseInt(document.getElementById('admin-reward').value,10);const tier=document.getElementById('admin-tier').value;const st=document.getElementById('admin-status').value;const el=document.getElementById('admin-eligibility').value.trim();const ins=document.getElementById('admin-instructions').value.trim();const url=adminSurveyType==='external'?document.getElementById('admin-url').value.trim():'';b.disabled=true;n.className='notice';try{if(!t||!d)throw new Error('Title + description required');if(isNaN(dur)||dur<=0)throw new Error('Invalid duration');if(isNaN(rw)||rw<=0)throw new Error('Invalid reward');if(!PLANS[tier])throw new Error('Invalid tier');if(adminSurveyType==='external'){if(!url.startsWith('https://'))throw new Error('URL must be HTTPS');if(url.indexOf('forms.gle/example')!==-1)throw new Error('Demo link');}else{if(adminQuestions.length===0)throw new Error('Add question');for(let i=0;i<adminQuestions.length;i++){const q=adminQuestions[i];if(!q.question.trim())throw new Error('Q'+(i+1)+' empty');if(q.type==='mcq'){const f=(q.options||[]).filter(o=>o.trim());if(f.length<2)throw new Error('Q'+(i+1)+' needs 2+ options');if(q.screenOut&&(!q.correctOptions||q.correctOptions.length===0))throw new Error('Q'+(i+1)+' screen-out needs correct answer');}}}const all=readStore(STORE_SURVEYS,[]);const ns={id:uid('sur'),title:t,category:cat,description:d,estimated_minutes:dur,duration:dur+' mins',status:st,tier:tier,reward:rw,eligibility:el,instructions:ins,type:adminSurveyType,created_at:Date.now()};if(adminSurveyType==='external')ns.survey_url=url;else ns.questions=adminQuestions.map(q=>{const m={id:q.id,type:q.type,question:q.question,required:q.required};if(q.type==='mcq'){m.options=q.options.filter(o=>o.trim());m.screenOut=!!q.screenOut;m.correctOptions=q.screenOut?(q.correctOptions||[]):[];}else m.options=[];return m;});all.push(ns);writeStore(STORE_SURVEYS,all);n.className='notice show success';n.textContent='Survey created!';showToast('Published');e.target.reset();adminQuestions=[];adminSurveyType='external';setAdminSurveyType('external');renderAdminQuestions();fetchAndRenderSurveys();}catch(err){n.className='notice show error';n.textContent='Error: '+err.message;}finally{b.disabled=false;}}
async function toggleSurveyStatus(id,ns){try{const all=readStore(STORE_SURVEYS,[]);const i=all.findIndex(s=>s.id===id);if(i===-1)throw new Error('Not found');all[i].status=ns;writeStore(STORE_SURVEYS,all);showToast('Status: '+ns);fetchAndRenderSurveys();await loadAdminSurveysTable();}catch(e){showToast(e.message);}}
async function deleteSurvey(id){if(!confirm('Delete survey? Cannot be undone.'))return;try{let all=readStore(STORE_SURVEYS,[]);all=all.filter(s=>s.id!==id);writeStore(STORE_SURVEYS,all);let p=readStore(STORE_PARTICIPATIONS,[]);p=p.filter(x=>x.survey_id!==id);writeStore(STORE_PARTICIPATIONS,p);let r=readStore(STORE_RESPONSES,[]);r=r.filter(x=>x.survey_id!==id);writeStore(STORE_RESPONSES,r);showToast('Deleted');fetchAndRenderSurveys();await loadAdminSurveysTable();await loadAdminParticipationsTable();}catch(e){showToast(e.message);}}
function exportCSV(){const ps=readStore(STORE_PARTICIPATIONS,[]),ss=readStore(STORE_SURVEYS,[]),us=readStore(STORE_USERS,[]);const rows=[['ID','User','Username','Email','Survey','Status','Review','Reward','Submitted']];ps.forEach(p=>{const u=us.find(x=>x.id===p.user_id),s=ss.find(x=>x.id===p.survey_id);rows.push([p.id,u?(u.name||''):'',u?'@'+(u.username||''):'',u?u.email:'',s?s.title:'Deleted',p.status||'',p.review_status||'',s?s.reward||0:0,p.submitted_at?new Date(p.submitted_at).toISOString():'']);});const csv=rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='surveyke-'+todayStr()+'.csv';a.click();}

function loadAdminWithdrawals(){const w=document.getElementById('admin-withdrawals-wrap');if(!w)return;const all=readStore(STORE_WITHDRAWALS,[]).slice().sort((a,b)=>(b.created_at||0)-(a.created_at||0));if(all.length===0){w.innerHTML='<div class="state-box"><strong>No withdrawals yet</strong></div>';return;}const us=readStore(STORE_USERS,[]);w.innerHTML=all.map(wd=>{const u=us.find(x=>x.id===wd.user_id);const un=u?(u.name||u.email):'Unknown';const ue=u?(u.email||''):'';const dt=new Date(wd.created_at).toLocaleString();const method=wd.method||'mpesa';const mBadge=method==='crypto'?`<span class="withdrawal-method-badge crypto">₮ USDT BEP20</span>`:`<span class="withdrawal-method-badge mpesa">📱 M-Pesa</span>`;const dest=method==='crypto'?wd.usdt_address:wd.phone;const destDisplay=dest?(method==='crypto'?escapeHtml(dest):escapeHtml(dest)):'';let acts='';if(wd.status==='pending')acts=`<button class="admin-act-btn admin-act-review" onclick="updateWithdrawal('${wd.id}','processing')">Processing</button><button class="admin-act-btn admin-act-delete" onclick="updateWithdrawal('${wd.id}','rejected')">Reject</button>`;else if(wd.status==='processing')acts=`<button class="admin-act-btn admin-act-approve" onclick="updateWithdrawal('${wd.id}','completed')">Complete</button>`;else acts=`<span class="withdrawal-status ${wd.status}">${wd.status}</span>`;return `<div class="withdrawal-row"><div class="withdrawal-row-main"><strong>${mBadge} @${escapeHtml(u?(u.username||''):'')} — KSh ${wd.amount}</strong><small>${escapeHtml(un)} · ${escapeHtml(ue)} · ${dt}</small><div class="withdrawal-destination">${method==='crypto'?'USDT: ':'M-Pesa: '}${destDisplay}</div></div><div class="withdrawal-row-actions">${acts}</div></div>`;}).join('');}
function updateWithdrawal(id,st){try{const all=readStore(STORE_WITHDRAWALS,[]);const i=all.findIndex(w=>w.id===id);if(i===-1)throw new Error('Not found');all[i].status=st;all[i].updated_at=Date.now();writeStore(STORE_WITHDRAWALS,all);showToast('Withdrawal '+st);loadAdminWithdrawals();if(st==='completed'&&window.confetti)confetti({particleCount:80,spread:60});}catch(e){showToast(e.message);}}

function loadAdminPromos(){const l=document.getElementById('admin-promos-list');if(!l)return;const ps=readStore(STORE_PROMOS,[]);if(ps.length===0){l.innerHTML='<div class="state-box"><strong>No promos</strong></div>';return;}l.innerHTML=ps.slice().reverse().map(p=>`<div class="promo-item"><div><strong>${escapeHtml(p.code)}</strong> <small>— KSh ${p.amount} · ${(p.uses||[]).length}/${p.maxUses||'∞'} used</small></div><button class="admin-act-btn admin-act-delete" onclick="deletePromo('${p.code}')">Delete</button></div>`).join('');}
function createPromo(){const c=document.getElementById('promo-code-input').value.trim().toUpperCase();const a=parseInt(document.getElementById('promo-amount-input').value,10);const m=parseInt(document.getElementById('promo-maxuses-input').value,10)||100;if(!c||c.length<3){showToast('Code 3+ chars');return;}if(isNaN(a)||a<=0||a>1000){showToast('Amount 1-1000');return;}const ps=readStore(STORE_PROMOS,[]);if(ps.some(x=>x.code===c)){showToast('Exists');return;}ps.push({code:c,amount:a,maxUses:m,uses:[],created_at:Date.now()});writeStore(STORE_PROMOS,ps);document.getElementById('promo-code-input').value='';document.getElementById('promo-amount-input').value='';showToast('Created: '+c);loadAdminPromos();}
function deletePromo(c){if(!confirm('Delete '+c+'?'))return;const ps=readStore(STORE_PROMOS,[]).filter(x=>x.code!==c);writeStore(STORE_PROMOS,ps);loadAdminPromos();showToast('Deleted');}

function renderAdminWallet(){const c=document.getElementById('wallet-content');const us=readStore(STORE_USERS,[]),ps=readStore(STORE_PARTICIPATIONS,[]),ss=readStore(STORE_SURVEYS,[]),ws=readStore(STORE_WITHDRAWALS,[]);const ru=us.filter(u=>u.email.toLowerCase()!==ADMIN_EMAIL.toLowerCase());const cw=ws.filter(w=>w.status==='completed');const pw=ws.filter(w=>w.status==='pending'||w.status==='processing');const paidOut=cw.reduce((s,w)=>s+w.amount,0);const pendPay=pw.reduce((s,w)=>s+w.amount,0);const ui=ru.map(u=>{const up=ps.filter(p=>p.user_id===u.id);const bal=getUserBalance(u.id);const uw=ws.filter(w=>w.user_id===u.id);const upaid=uw.filter(w=>w.status==='completed').reduce((s,w)=>s+w.amount,0);const upend=uw.filter(w=>w.status==='pending'||w.status==='processing').reduce((s,w)=>s+w.amount,0);return {user:u,balance:bal,userPaid:upaid,userPending:upend,surveys:up.length};}).sort((a,b)=>b.balance.available-a.balance.available);const stats=`<div class="admin-user-stats"><div class="admin-stat-tile"><span class="val">${ru.length}</span><span class="lbl">Users</span></div><div class="admin-stat-tile"><span class="val">KSh ${paidOut.toLocaleString()}</span><span class="lbl">Paid Out</span></div><div class="admin-stat-tile"><span class="val">KSh ${pendPay.toLocaleString()}</span><span class="lbl">Pending</span></div><div class="admin-stat-tile"><span class="val">${ps.length}</span><span class="lbl">Participations</span></div></div>`;const pendH=pw.length>0?`<div class="admin-wallet-section"><h3>⏳ Pending Withdrawals <span class="badge-count">${pw.length}</span></h3><div class="user-list">${pw.map(w=>{const u=us.find(x=>x.id===w.user_id);const ml=w.method==='crypto'?'USDT BEP20':'M-Pesa';const dest=w.method==='crypto'?w.usdt_address:w.phone;return `<div class="user-item"><div class="user-info"><strong>@${escapeHtml(u?u.username||'':'')} — KSh ${w.amount}</strong><small>${ml}: ${escapeHtml(dest||'')}</small><small style="color:var(--amber);">${w.status} · ${new Date(w.created_at).toLocaleDateString()}</small></div><div class="user-stats"><div class="user-stat"><span class="user-stat-val">KSh ${w.amount}</span><span class="user-stat-lbl">Amount</span></div></div></div>`;}).join('')}</div></div>`:'';const paidH=cw.length>0?`<div class="admin-wallet-section"><h3>✅ Completed <span class="badge-count">${cw.length}</span></h3><div class="user-list">${cw.slice(0,10).map(w=>{const u=us.find(x=>x.id===w.user_id);const ml=w.method==='crypto'?'USDT':'M-Pesa';const dest=w.method==='crypto'?w.usdt_address:w.phone;return `<div class="user-item"><div class="user-info"><strong>@${escapeHtml(u?u.username||'':'')} — KSh ${w.amount}</strong><small>${ml}: ${escapeHtml(dest||'')}</small><small style="color:var(--green);">Completed ${new Date(w.updated_at).toLocaleDateString()}</small></div></div>`;}).join('')}</div></div>`:'';const usersH=ui.length===0?'<div class="state-box"><strong>No users</strong></div>':'<div class="user-list">'+ui.map(item=>{const u=item.user;const init=(u.name||u.email||'?').charAt(0).toUpperCase();const avH=u.avatar?`<img src="${escapeHtml(u.avatar)}">`:escapeHtml(init);return `<div class="user-item" style="cursor:pointer;" onclick="viewAdminUser('${u.id}')"><div class="user-avatar">${avH}</div><div class="user-info"><strong>${escapeHtml(u.name||'User')}</strong><small>@${escapeHtml(u.username||'')} · ${escapeHtml(u.email)}</small><small>${PLANS[u.tier||'basic'].label}</small></div><div class="user-stat-split"><div><span class="label">Paid</span><span class="val">KSh ${item.userPaid}</span></div><div><span class="label">Pending</span><span class="val pending">KSh ${item.userPending}</span></div></div></div>`;}).join('')+'</div>';c.innerHTML=`<div class="wallet-header"><h2>Users Overview</h2><p>Platform stats and user financials</p></div>${stats}${pendH}${paidH}<div class="admin-wallet-section"><h3>👥 All Users</h3>${usersH}</div>`;}

function openAuth(m){document.getElementById('auth-overlay').classList.add('open');switchAuthMode(m);clearAuthNotices();}
function closeAuth(){document.getElementById('auth-overlay').classList.remove('open');}
function handleOverlayClick(e){if(e.target.id==='auth-overlay')closeAuth();}
function switchAuthMode(m){clearAuthNotices();const si=document.getElementById('form-signin'),su=document.getElementById('form-signup');if(m==='signin'){si.classList.remove('hidden');su.classList.add('hidden');}else{si.classList.add('hidden');su.classList.remove('hidden');}}
function showNotice(m,t){const n=document.getElementById('auth-notice');n.className='notice show '+t;n.textContent=m;}
function clearAuthNotices(){const n=document.getElementById('auth-notice');n.className='notice';n.textContent='';}
function findUserByEmailOrUsername(i){const l=i.toLowerCase();return readStore(STORE_USERS,[]).find(u=>u.email.toLowerCase()===l||(u.username||'').toLowerCase()===l);}
async function submitSignIn(e){e.preventDefault();const id=document.getElementById('signin-email').value.trim();const pw=document.getElementById('signin-password').value;const b=document.getElementById('signin-submit-btn');b.disabled=true;clearAuthNotices();try{if(!id||!pw)throw new Error('Enter credentials');const u=findUserByEmailOrUsername(id);if(!u)throw new Error('No account found');const h=await hashPassword(pw);if(u.passwordHash!==h)throw new Error('Wrong password');currentUser={id:u.id,email:u.email,name:u.name||u.email.split('@')[0],username:u.username||u.email.split('@')[0],avatar:u.avatar||null,tier:u.tier||'basic',referralCode:u.referralCode||ensureReferralCode(u),referrals:u.referrals||[]};isAdmin=u.email.toLowerCase()===ADMIN_EMAIL.toLowerCase();writeStore(STORE_SESSION,{userId:u.id});const us=readStore(STORE_USERS,[]);const idx=us.findIndex(x=>x.id===u.id);if(idx!==-1){us[idx].logins=us[idx].logins||[];us[idx].logins.push({time:Date.now(),ua:navigator.userAgent});if(us[idx].logins.length>20)us[idx].logins=us[idx].logins.slice(-20);writeStore(STORE_USERS,us);}ensureDailyReset();updateAuthUI();closeAuth();showToast('Welcome @'+currentUser.username+'!');fetchAndRenderSurveys();checkStreak();checkAchievements();if(currentView==='profile')renderProfile();if(currentView==='wallet')renderWallet();updateNotifBadges();}catch(err){showNotice(err.message,'error');}finally{b.disabled=false;}}
async function submitSignUp(e){e.preventDefault();const n=document.getElementById('signup-name').value.trim();const un=document.getElementById('signup-username').value.trim().toLowerCase();const em=document.getElementById('signup-email').value.trim().toLowerCase();const pw=document.getElementById('signup-password').value;const rc=document.getElementById('signup-referral').value.trim().toUpperCase();const rl=document.getElementById('signup-rules').checked;const b=document.getElementById('signup-submit-btn');b.disabled=true;clearAuthNotices();try{if(!n||n.length<2)throw new Error('Enter your name');if(!un||un.length<3||un.length>20)throw new Error('Username 3-20 chars');if(!/^[a-z0-9_]+$/.test(un))throw new Error('Username: lowercase, numbers, underscore');if(!em||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em))throw new Error('Valid email');if(!pw||pw.length<6)throw new Error('Password 6+');if(!rl)throw new Error('Agree to Terms');const us=readStore(STORE_USERS,[]);if(us.some(u=>u.email.toLowerCase()===em))throw new Error('Email taken');if(us.some(u=>(u.username||'').toLowerCase()===un))throw new Error('Username taken');let ref=null;if(rc){ref=us.find(u=>(u.referralCode||'').toUpperCase()===rc);if(!ref)throw new Error('Invalid referral code');}const h=await hashPassword(pw);const nu={id:uid('user'),name:n,username:un,email:em,passwordHash:h,avatar:null,tier:'basic',referralCode:null,referrals:[],bonuses:[],achievements:[],logins:[{time:Date.now(),ua:navigator.userAgent}],referred_by:ref?ref.referralCode:null,daily:{date:todayStr(),surveyCount:0,totalRewards:0},notifications_read_at:Date.now(),created_at:Date.now(),agreedToRules:true};nu.referralCode=generateReferralCode(nu.id);us.push(nu);writeStore(STORE_USERS,us);if(ref){const idx=us.findIndex(u=>u.id===ref.id);if(idx!==-1){us[idx].referrals=us[idx].referrals||[];us[idx].referrals.push(nu.id);writeStore(STORE_USERS,us);}}localStorage.removeItem(STORE_PENDING_REF);currentUser={id:nu.id,email:nu.email,name:nu.name,username:nu.username,avatar:null,tier:'basic',referralCode:nu.referralCode,referrals:[]};isAdmin=nu.email.toLowerCase()===ADMIN_EMAIL.toLowerCase();writeStore(STORE_SESSION,{userId:nu.id});updateAuthUI();closeAuth();showToast('Welcome @'+un+'!');fetchAndRenderSurveys();checkStreak();checkAchievements();updateNotifBadges();if(currentView==='profile')renderProfile();if(currentView==='wallet')renderWallet();}catch(err){showNotice(err.message,'error');}finally{b.disabled=false;}}
async function submitPasswordReset(){showNotice('Local-only mode: not available.','info');}
async function signOut(){writeStore(STORE_SESSION,null);currentUser=null;isAdmin=false;updateAuthUI();if(currentView==='profile')renderProfile();else if(currentView==='wallet')renderWallet();else if(currentView==='notifications')renderNotifications();else if(currentView==='settings')renderSettings();else navigate('home');updateNotifBadges();showToast('Signed out');}
function updateAuthUI(){const g=document.getElementById('auth-guest-actions'),u=document.getElementById('auth-user-actions'),gr=document.getElementById('user-greeting'),al=document.getElementById('nav-admin-link');if(currentUser){g.classList.add('hidden');g.style.display='none';u.classList.remove('hidden');u.style.display='flex';gr.textContent='Hi, @'+(currentUser.username||currentUser.name||'');if(isAdmin)al.classList.remove('hidden');else al.classList.add('hidden');}else{u.classList.add('hidden');u.style.display='none';g.classList.remove('hidden');g.style.display='flex';al.classList.add('hidden');}}

document.addEventListener('keydown',e=>{if(!wizard.active)return;const q=wizard.survey.questions[wizard.currentIndex];if(!q)return;if(q.type==='mcq'){if(e.key>='1'&&e.key<='9'){const idx=parseInt(e.key)-1;const bs=document.querySelectorAll('.wizard-option-btn');if(bs[idx]&&!wizard.locked)bs[idx].click();}const letters='abcdefghij';const li=letters.indexOf(e.key.toLowerCase());if(li!==-1&&li<(q.options||[]).length){const bs=document.querySelectorAll('.wizard-option-btn');if(bs[li]&&!wizard.locked)bs[li].click();}}if(e.key==='Enter'&&!e.shiftKey){const b=document.getElementById('wizard-next-btn');if(b&&!b.disabled){e.preventDefault();b.click();}}if(e.key==='ArrowLeft'){const p=document.querySelector('.wizard-prev-btn');if(p&&!p.disabled)p.click();}});

function escapeHtml(s){if(!s)return '';return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');}
function showToast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3500);}
